insert into public.recipes (id, name, description, meal_type, main, emoji, prep_time_min, difficulty, calories, protein_g, carbs_g, fat_g, fiber_g, sugar_g, sodium_mg, ingredients, seasonings, instructions, appliances, keywords, dietary_tags, i18n, sort) values
  ('b-banana-peanut-butter-oatmeal', 'Banana Peanut Butter Oatmeal', 'Creamy stovetop oats with sliced banana and a spoon of peanut butter', 'breakfast', 'oats', '🥣', 10, 'quick', 553, 21, 84, 17, 10, 30, 190, '[{"name":"oats","amount":60,"unit":"g"},{"name":"milk","amount":250,"unit":"ml"},{"name":"banana","amount":1,"unit":"","label":"1 banana"},{"name":"peanut butter","amount":15,"unit":"g"}]'::jsonb, '["pinch of salt","pinch of cinnamon"]'::jsonb, '["Put the oats, milk and a pinch of salt in a small pot over medium heat","Simmer for 4 to 5 minutes, stirring often, until thick and creamy","Slice the banana and stir half of it into the oats","Pour into a bowl and top with the rest of the banana, the peanut butter and a little cinnamon"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","hearty","oats","milk","banana","peanut butter","stovetop","breakfast"]'::jsonb, '["vegetarian","halal","kosher"]'::jsonb, '{"bg":{"name":"Овесена каша с банан и фъстъчено масло","description":"Кремообразна овесена каша с резенчета банан и лъжица фъстъчено масло","instructions":["Сложете овесените ядки, млякото и щипка сол в малка тенджера на среден огън","Варете на тих огън 4–5 минути, като бъркате често, докато кашата стане гъста и кремообразна","Нарежете банана на резенчета и разбъркайте половината в кашата","Изсипете в купа и сложете отгоре останалия банан, фъстъченото масло и малко канела"],"seasonings":["щипка сол","щипка канела"]},"nl":{"name":"Havermout met banaan en pindakaas","description":"Romige havermout uit de pan met plakjes banaan en een lepel pindakaas","instructions":["Doe de havermout, de melk en een snufje zout in een pannetje op middelhoog vuur","Laat 4 tot 5 minuten zachtjes koken en roer vaak, tot het dik en romig is","Snijd de banaan in plakjes en roer de helft door de havermout","Schenk in een kom en leg de rest van de banaan, de pindakaas en een beetje kaneel erop"],"seasonings":["snufje zout","snufje kaneel"]}}'::jsonb, 0),
  ('b-apple-cinnamon-oatmeal', 'Apple Cinnamon Oatmeal', 'Warm oats cooked with diced apple, cinnamon and a drizzle of honey', 'breakfast', 'oats', '🍎', 12, 'quick', 480, 17, 86, 9, 10, 41, 127, '[{"name":"oats","amount":60,"unit":"g"},{"name":"milk","amount":250,"unit":"ml"},{"name":"apple","amount":1,"unit":"","label":"1 apple"},{"name":"honey","amount":10,"unit":"g"}]'::jsonb, '["1/2 tsp cinnamon","pinch of salt"]'::jsonb, '["Core the apple and cut it into small cubes","Put the oats, milk, cinnamon, salt and two thirds of the apple in a small pot","Simmer over medium heat for 5 to 6 minutes, stirring often, until the oats are soft","Serve topped with the remaining apple and the honey"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","oats","milk","apple","honey","stovetop","breakfast"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Овесена каша с ябълка и канела","description":"Топла овесена каша с кубчета ябълка, канела и малко мед","instructions":["Почистете ябълката от семките и я нарежете на малки кубчета","Сложете овесените ядки, млякото, канелата, солта и две трети от ябълката в малка тенджера","Варете на среден огън 5–6 минути, като бъркате често, докато ядките омекнат","Поднесете с останалата ябълка и меда отгоре"],"seasonings":["1/2 ч.л. канела","щипка сол"]},"nl":{"name":"Havermout met appel en kaneel","description":"Warme havermout met blokjes appel, kaneel en een beetje honing","instructions":["Verwijder het klokhuis van de appel en snijd hem in kleine blokjes","Doe de havermout, de melk, de kaneel, het zout en twee derde van de appel in een pannetje","Laat 5 tot 6 minuten zachtjes koken op middelhoog vuur en roer vaak, tot de havermout zacht is","Serveer met de rest van de appel en de honing erop"],"seasonings":["1/2 tl kaneel","snufje zout"]}}'::jsonb, 1),
  ('b-coconut-berry-overnight-oats', 'Coconut Berry Overnight Oats', 'No-cook oats soaked overnight in coconut milk, topped with berries', 'breakfast', 'oats', '🫐', 5, 'quick', 456, 11, 61, 21, 10, 13, 16, '[{"name":"oats","amount":60,"unit":"g"},{"name":"coconut milk","amount":80,"unit":"g"},{"name":"blueberries","amount":80,"unit":"g"},{"name":"strawberries","amount":80,"unit":"g"}]'::jsonb, '["{120} ml water","pinch of salt"]'::jsonb, '["Stir the oats, coconut milk, water and salt together in a jar or bowl","Cover and leave in the fridge overnight, or for at least 4 hours","In the morning stir well and loosen with a splash of water if it is too thick","Slice the strawberries and serve the oats topped with both berries"]'::jsonb, '[]'::jsonb, '["fresh","quick","oats","coconut milk","blueberries","strawberries","breakfast"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Нощни овесени ядки с кокос и горски плодове","description":"Овесени ядки без варене, накиснати за една нощ в кокосово мляко, с плодове отгоре","instructions":["Разбъркайте овесените ядки, кокосовото мляко, водата и солта в буркан или купа","Покрийте и оставете в хладилника за една нощ или поне за 4 часа","На сутринта разбъркайте добре и разредете с малко вода, ако е твърде гъсто","Нарежете ягодите на резенчета и поднесете ядките с двата вида плодове отгоре"],"seasonings":["{120} мл вода","щипка сол"]},"nl":{"name":"Overnight oats met kokos en bessen","description":"Havermout die een nacht weekt in kokosmelk, zonder koken, met bessen erop","instructions":["Roer de havermout, de kokosmelk, het water en het zout door elkaar in een pot of kom","Dek af en zet een nacht in de koelkast, of minstens 4 uur","Roer ''s ochtends goed door en maak het losser met een scheutje water als het te dik is","Snijd de aardbeien in plakjes en serveer de havermout met beide soorten fruit erop"],"seasonings":["{120} ml water","snufje zout"]}}'::jsonb, 2),
  ('b-peanut-butter-banana-toast', 'Peanut Butter Banana Toast', 'Toasted wholemeal bread with peanut butter and banana slices', 'breakfast', 'bread', '🍌', 5, 'quick', 463, 17, 64, 18, 9, 21, 448, '[{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"peanut butter","amount":30,"unit":"g"},{"name":"banana","amount":1,"unit":"","label":"1 banana"}]'::jsonb, '["pinch of cinnamon"]'::jsonb, '["Toast the bread until golden","Spread the peanut butter over both slices","Slice the banana, lay it on top and dust with cinnamon"]'::jsonb, '[]'::jsonb, '["quick","bread","peanut butter","banana","breakfast"]'::jsonb, '["vegetarian","vegan","dairy-free","halal","kosher"]'::jsonb, '{"bg":{"name":"Препечена филийка с фъстъчено масло и банан","description":"Препечен пълнозърнест хляб с фъстъчено масло и резенчета банан","instructions":["Препечете хляба до златисто","Намажете двете филийки с фъстъченото масло","Нарежете банана на резенчета, наредете го отгоре и поръсете с канела"],"seasonings":["щипка канела"]},"nl":{"name":"Toast met pindakaas en banaan","description":"Geroosterd volkorenbrood met pindakaas en plakjes banaan","instructions":["Rooster het brood goudbruin","Besmeer beide sneetjes met de pindakaas","Snijd de banaan in plakjes, leg ze erop en bestrooi met kaneel"],"seasonings":["snufje kaneel"]}}'::jsonb, 3),
  ('b-avocado-tomato-toast', 'Avocado Tomato Toast', 'Smashed avocado on toast with fresh tomato, lemon and olive oil', 'breakfast', 'avocado', '🥑', 8, 'quick', 463, 12, 46, 28, 15, 7, 333, '[{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"tomato","amount":100,"unit":"g"},{"name":"olive oil","amount":5,"unit":"g"}]'::jsonb, '["salt","black pepper","squeeze of lemon juice","pinch of chili flakes"]'::jsonb, '["Toast the bread","Halve the avocado, scoop the flesh into a bowl and mash it with a fork, salt, pepper and a squeeze of lemon","Slice the tomato","Spread the avocado on the toast, top with tomato, drizzle with the olive oil and finish with chili flakes"]'::jsonb, '[]'::jsonb, '["spicy","fresh","quick","bread","avocado","tomato","olive oil","breakfast"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Препечена филийка с авокадо и домат","description":"Намачкано авокадо върху препечен хляб с пресен домат, лимон и зехтин","instructions":["Препечете хляба","Разрежете авокадото наполовина, извадете месестата част в купа и я намачкайте с вилица, сол, пипер и няколко капки лимон","Нарежете домата на резенчета","Намажете авокадото върху филийките, сложете домата, полейте със зехтина и поръсете с люспи чили"],"seasonings":["сол","черен пипер","няколко капки лимонов сок","щипка люспи чили"]},"nl":{"name":"Toast met avocado en tomaat","description":"Geprakte avocado op toast met verse tomaat, citroen en olijfolie","instructions":["Rooster het brood","Halveer de avocado, schep het vruchtvlees in een kom en prak het met een vork, zout, peper en een kneepje citroen","Snijd de tomaat in plakjes","Smeer de avocado op de toast, leg de tomaat erop, besprenkel met de olijfolie en maak af met chilivlokken"],"seasonings":["zout","zwarte peper","kneepje citroensap","snufje chilivlokken"]}}'::jsonb, 4),
  ('b-avocado-egg-toast', 'Avocado Toast with Fried Eggs', 'Wholemeal toast with smashed avocado and two fried eggs', 'breakfast', 'eggs', '🍳', 10, 'quick', 602, 25, 43, 38, 14, 4, 485, '[{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["salt","black pepper","pinch of chili flakes"]'::jsonb, '["Toast the bread","Mash the avocado with salt and pepper and spread it over the toast","Heat the oil in a pan over medium heat and fry the eggs for 2 to 3 minutes until the whites are set","Slide an egg onto each slice and season with pepper and chili flakes"]'::jsonb, '["stovetop"]'::jsonb, '["spicy","quick","hearty","bread","avocado","eggs","oil","stovetop","breakfast"]'::jsonb, '["vegetarian","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Филийка с авокадо и яйца на очи","description":"Пълнозърнеста препечена филийка с намачкано авокадо и две яйца на очи","instructions":["Препечете хляба","Намачкайте авокадото със сол и пипер и го намажете върху филийките","Загрейте олиото в тиган на среден огън и изпържете яйцата за 2–3 минути, докато белтъкът стегне","Сложете по едно яйце върху всяка филийка и поръсете с пипер и люспи чили"],"seasonings":["сол","черен пипер","щипка люспи чили"]},"nl":{"name":"Avocadotoast met gebakken eieren","description":"Volkorentoast met geprakte avocado en twee gebakken eieren","instructions":["Rooster het brood","Prak de avocado met zout en peper en smeer hem op de toast","Verhit de olie in een pan op middelhoog vuur en bak de eieren 2 tot 3 minuten, tot het eiwit gestold is","Laat op elk sneetje een ei glijden en bestrooi met peper en chilivlokken"],"seasonings":["zout","zwarte peper","snufje chilivlokken"]}}'::jsonb, 5),
  ('b-greek-yogurt-berry-bowl', 'Greek Yogurt Berry Bowl', 'Thick Greek yogurt with blueberries, strawberries and honey', 'breakfast', 'greek yogurt', '🍓', 5, 'quick', 355, 24, 39, 13, 3, 33, 90, '[{"name":"greek yogurt","amount":250,"unit":"g"},{"name":"blueberries","amount":75,"unit":"g"},{"name":"strawberries","amount":75,"unit":"g"},{"name":"honey","amount":15,"unit":"g"}]'::jsonb, '[]'::jsonb, '["Spoon the yogurt into a bowl","Halve or slice the strawberries","Top the yogurt with the berries and drizzle with the honey"]'::jsonb, '[]'::jsonb, '["fresh","quick","light","greek yogurt","blueberries","strawberries","honey","breakfast"]'::jsonb, '["vegetarian","gluten-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Купа гръцко кисело мляко с плодове","description":"Гъсто гръцко кисело мляко с боровинки, ягоди и мед","instructions":["Сипете киселото мляко в купа","Разрежете ягодите наполовина или на резенчета","Сложете плодовете върху млякото и полейте с меда"],"seasonings":[]},"nl":{"name":"Griekse yoghurt met bessen","description":"Dikke Griekse yoghurt met blauwe bessen, aardbeien en honing","instructions":["Schep de yoghurt in een kom","Halveer de aardbeien of snijd ze in plakjes","Leg het fruit op de yoghurt en besprenkel met de honing"],"seasonings":[]}}'::jsonb, 6),
  ('b-apple-bircher-muesli', 'Apple Bircher Muesli', 'Oats soaked in yogurt with grated apple and honey', 'breakfast', 'yogurt', '🥣', 10, 'quick', 398, 13, 70, 9, 8, 37, 97, '[{"name":"yogurt","amount":200,"unit":"g"},{"name":"oats","amount":40,"unit":"g"},{"name":"apple","amount":1,"unit":"","label":"1 apple"},{"name":"honey","amount":10,"unit":"g"}]'::jsonb, '["pinch of cinnamon"]'::jsonb, '["Coarsely grate the apple, leaving the core behind","Stir the oats, yogurt, grated apple and cinnamon together in a bowl","Leave for at least 10 minutes, or overnight in the fridge, so the oats soften","Drizzle with the honey before serving"]'::jsonb, '[]'::jsonb, '["fresh","quick","light","yogurt","oats","apple","honey","breakfast"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Бирхер мюсли с ябълка","description":"Овесени ядки, накиснати в кисело мляко, с настъргана ябълка и мед","instructions":["Настържете ябълката на едро, без сърцевината","Разбъркайте овесените ядки, киселото мляко, настърганата ябълка и канелата в купа","Оставете поне 10 минути или за една нощ в хладилника, за да омекнат ядките","Полейте с меда преди поднасяне"],"seasonings":["щипка канела"]},"nl":{"name":"Birchermuesli met appel","description":"Havermout geweekt in yoghurt met geraspte appel en honing","instructions":["Rasp de appel grof en laat het klokhuis over","Roer de havermout, de yoghurt, de geraspte appel en de kaneel door elkaar in een kom","Laat minstens 10 minuten staan, of een nacht in de koelkast, zodat de havermout zacht wordt","Besprenkel voor het serveren met de honing"],"seasonings":["snufje kaneel"]}}'::jsonb, 7),
  ('b-spinach-feta-scrambled-eggs', 'Spinach and Feta Scrambled Eggs', 'Soft scrambled eggs with wilted spinach, feta and fresh tomato', 'breakfast', 'eggs', '🍳', 10, 'quick', 414, 30, 10, 29, 3, 4, 790, '[{"name":"eggs","amount":3,"unit":"","label":"3 eggs"},{"name":"spinach","amount":80,"unit":"g"},{"name":"feta","amount":40,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"butter","amount":5,"unit":"g"}]'::jsonb, '["black pepper"]'::jsonb, '["Beat the eggs with a little pepper; the feta is salty, so add no salt","Melt the butter in a pan over medium heat and wilt the spinach for about 1 minute","Pour in the eggs and stir gently for 2 to 3 minutes until just set","Crumble in the feta, fold once and serve with the sliced tomato"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","quick","eggs","spinach","feta","tomato","butter","stovetop","breakfast"]'::jsonb, '["vegetarian","gluten-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Бъркани яйца със спанак и фета","description":"Меки бъркани яйца със задушен спанак, фета и пресен домат","instructions":["Разбийте яйцата с малко пипер; фетата е солена, затова не добавяйте сол","Разтопете маслото в тиган на среден огън и задушете спанака за около 1 минута","Изсипете яйцата и бъркайте леко 2–3 минути, докато едва стегнат","Натрошете фетата, разбъркайте веднъж и поднесете с нарязания домат"],"seasonings":["черен пипер"]},"nl":{"name":"Roerei met spinazie en feta","description":"Zacht roerei met geslonken spinazie, feta en verse tomaat","instructions":["Klop de eieren los met een beetje peper; de feta is zout, dus voeg geen zout toe","Smelt de boter in een pan op middelhoog vuur en laat de spinazie ongeveer 1 minuut slinken","Giet de eieren erbij en roer 2 tot 3 minuten voorzichtig, tot ze net gestold zijn","Verkruimel de feta erboven, schep één keer om en serveer met de plakjes tomaat"],"seasonings":["zwarte peper"]}}'::jsonb, 8),
  ('b-veggie-omelette', 'Pepper and Mushroom Omelette', 'A folded three-egg omelette filled with peppers, mushrooms and onion', 'breakfast', 'eggs', '🍳', 12, 'quick', 321, 24, 10, 21, 2, 6, 241, '[{"name":"eggs","amount":3,"unit":"","label":"3 eggs"},{"name":"peppers","amount":60,"unit":"g"},{"name":"mushrooms","amount":60,"unit":"g"},{"name":"onion","amount":30,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Dice the pepper and onion and slice the mushrooms","Heat the oil in a non-stick pan and cook the vegetables for 4 to 5 minutes until soft, then tip them onto a plate","Beat the eggs with salt and pepper, pour into the pan and cook over medium heat until almost set","Spoon the vegetables over one half, fold the omelette over and cook 1 more minute"]'::jsonb, '["stovetop"]'::jsonb, '["quick","light","eggs","peppers","mushrooms","onion","oil","stovetop","breakfast"]'::jsonb, '["vegetarian","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Омлет с чушка и гъби","description":"Сгънат омлет от три яйца с чушка, гъби и лук","instructions":["Нарежете чушката и лука на кубчета, а гъбите на филийки","Загрейте олиото в незалепващ тиган и гответе зеленчуците 4–5 минути, докато омекнат, след което ги прехвърлете в чиния","Разбийте яйцата със сол и пипер, изсипете ги в тигана и гответе на среден огън, докато почти стегнат","Разпределете зеленчуците върху едната половина, сгънете омлета и гответе още 1 минута"],"seasonings":["сол","черен пипер"]},"nl":{"name":"Omelet met paprika en champignons","description":"Een dubbelgeklapte omelet van drie eieren, gevuld met paprika, champignons en ui","instructions":["Snijd de paprika en de ui in blokjes en de champignons in plakjes","Verhit de olie in een koekenpan met antiaanbaklaag en bak de groenten 4 tot 5 minuten tot ze zacht zijn; schep ze dan op een bord","Klop de eieren los met zout en peper, giet ze in de pan en bak op middelhoog vuur tot ze bijna gestold zijn","Schep de groenten op één helft, klap de omelet dicht en bak nog 1 minuut"],"seasonings":["zout","zwarte peper"]}}'::jsonb, 9),
  ('b-ham-cheese-omelette', 'Ham and Cheese Omelette with Toast', 'A quick omelette with ham and melted cheese, served with buttered toast', 'breakfast', 'eggs', '🧀', 10, 'quick', 454, 32, 18, 27, 3, 3, 919, '[{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"ham","amount":40,"unit":"g"},{"name":"cheese","amount":30,"unit":"g"},{"name":"bread","amount":35,"unit":"g","label":"1 slice"},{"name":"butter","amount":5,"unit":"g"}]'::jsonb, '["black pepper"]'::jsonb, '["Beat the eggs with pepper, cut the ham into strips and grate the cheese","Melt half the butter in a non-stick pan over medium heat and pour in the eggs","When the eggs are almost set, scatter the ham and cheese over one half and fold the omelette over","Cook 1 more minute until the cheese melts and serve with the toasted, buttered bread"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","eggs","ham","cheese","bread","butter","stovetop","breakfast"]'::jsonb, '["nut-allergy"]'::jsonb, '{"bg":{"name":"Омлет с шунка и кашкавал и препечен хляб","description":"Бърз омлет с шунка и разтопен кашкавал, с препечена филийка с масло","instructions":["Разбийте яйцата с пипер, нарежете шунката на ивици и настържете кашкавала","Разтопете половината масло в незалепващ тиган на среден огън и изсипете яйцата","Когато яйцата почти стегнат, поръсете шунката и кашкавала върху едната половина и сгънете омлета","Гответе още 1 минута, докато кашкавалът се разтопи, и поднесете с препечения хляб, намазан с масло"],"seasonings":["черен пипер"]},"nl":{"name":"Omelet met ham en kaas en toast","description":"Een snelle omelet met ham en gesmolten kaas, met beboterde toast","instructions":["Klop de eieren los met peper, snijd de ham in reepjes en rasp de kaas","Smelt de helft van de boter in een koekenpan met antiaanbaklaag op middelhoog vuur en giet de eieren erin","Strooi de ham en de kaas over één helft als de eieren bijna gestold zijn en klap de omelet dicht","Bak nog 1 minuut tot de kaas smelt en serveer met het geroosterde, beboterde brood"],"seasonings":["zwarte peper"]}}'::jsonb, 10),
  ('b-bacon-eggs-toast', 'Bacon and Eggs with Toast', 'Crispy bacon, fried eggs and pan-warmed tomato with toast', 'breakfast', 'eggs', '🥓', 15, 'quick', 548, 30, 35, 32, 5, 6, 855, '[{"name":"bacon","amount":50,"unit":"g"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"tomato","amount":100,"unit":"g"}]'::jsonb, '["black pepper"]'::jsonb, '["Lay the bacon in a cold pan and cook over medium heat for 5 to 6 minutes, turning once, until crisp, then move it to a plate","Halve the tomato and fry it cut side down in the bacon fat for 2 minutes","Fry the eggs in the same pan for 2 to 3 minutes until the whites are set","Toast the bread and serve everything together with a little pepper"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","hearty","bacon","eggs","bread","tomato","stovetop","breakfast"]'::jsonb, '["dairy-free","nut-allergy"]'::jsonb, '{"bg":{"name":"Бекон с яйца и препечен хляб","description":"Хрупкав бекон, яйца на очи и запечен в тигана домат с препечен хляб","instructions":["Наредете бекона в студен тиган и го пържете на среден огън 5–6 минути, като го обърнете веднъж, докато стане хрупкав, след което го прехвърлете в чиния","Разрежете домата наполовина и го запържете с разреза надолу в мазнината от бекона за 2 минути","Изпържете яйцата в същия тиган за 2–3 минути, докато белтъкът стегне","Препечете хляба и поднесете всичко заедно с малко пипер"],"seasonings":["черен пипер"]},"nl":{"name":"Spek en eieren met toast","description":"Knapperig spek, gebakken eieren en in de pan verwarmde tomaat met toast","instructions":["Leg het spek in een koude pan en bak het 5 tot 6 minuten op middelhoog vuur knapperig; keer één keer en leg het dan op een bord","Halveer de tomaat en bak hem 2 minuten met de snijkant naar beneden in het spekvet","Bak de eieren 2 tot 3 minuten in dezelfde pan, tot het eiwit gestold is","Rooster het brood en serveer alles samen met een beetje peper"],"seasonings":["zwarte peper"]}}'::jsonb, 11),
  ('b-tofu-scramble-toast', 'Tofu Scramble on Toast', 'Golden scrambled tofu with spinach and peppers on wholemeal toast', 'breakfast', 'tofu', '🧈', 15, 'quick', 478, 37, 43, 21, 11, 7, 391, '[{"name":"tofu","amount":150,"unit":"g"},{"name":"spinach","amount":60,"unit":"g"},{"name":"peppers","amount":60,"unit":"g"},{"name":"onion","amount":30,"unit":"g"},{"name":"oil","amount":5,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"}]'::jsonb, '["1/2 tsp turmeric","salt","black pepper"]'::jsonb, '["Finely dice the onion and pepper and cook them in the oil over medium heat for 3 minutes","Crumble the tofu into the pan with your hands and add the turmeric, salt and pepper","Cook for 4 to 5 minutes, stirring, until the tofu is hot and lightly golden","Stir in the spinach until it wilts and pile the scramble onto the toasted bread"]'::jsonb, '["stovetop"]'::jsonb, '["quick","tofu","spinach","peppers","onion","oil","bread","stovetop","breakfast"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Бъркано тофу върху препечен хляб","description":"Златисто бъркано тофу със спанак и чушка върху пълнозърнеста филийка","instructions":["Нарежете лука и чушката на ситни кубчета и ги запържете в олиото на среден огън за 3 минути","Натрошете тофуто с ръце в тигана и добавете куркумата, сол и пипер","Гответе 4–5 минути, като бъркате, докато тофуто се затопли и леко се зачерви","Добавете спанака, бъркайте, докато омекне, и сложете сместа върху препечения хляб"],"seasonings":["1/2 ч.л. куркума","сол","черен пипер"]},"nl":{"name":"Roertofu op toast","description":"Goudgele roertofu met spinazie en paprika op volkorentoast","instructions":["Snijd de ui en de paprika in kleine blokjes en bak ze 3 minuten in de olie op middelhoog vuur","Verkruimel de tofu met je handen boven de pan en voeg de kurkuma, zout en peper toe","Bak 4 tot 5 minuten al roerend, tot de tofu heet en lichtgoud is","Roer de spinazie erdoor tot hij slinkt en schep de roertofu op het geroosterde brood"],"seasonings":["1/2 tl kurkuma","zout","zwarte peper"]}}'::jsonb, 12),
  ('b-chickpea-potato-hash', 'Chickpea and Potato Breakfast Hash', 'Crispy pan-fried potatoes with chickpeas, onion and spinach', 'breakfast', 'chickpeas', '🥔', 25, 'balanced', 441, 14, 68, 14, 14, 9, 349, '[{"name":"potatoes","amount":200,"unit":"g"},{"name":"chickpeas","amount":120,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"spinach","amount":50,"unit":"g"},{"name":"oil","amount":10,"unit":"g"}]'::jsonb, '["1/2 tsp smoked paprika","salt","black pepper"]'::jsonb, '["Cut the potatoes into 1 cm cubes and dice the onion","Heat the oil in a wide pan and fry the potatoes over medium heat for 12 to 15 minutes, turning now and then, until golden and tender","Add the onion, drained chickpeas, paprika, salt and pepper and cook 4 more minutes","Stir in the spinach until it wilts and serve hot"]'::jsonb, '["stovetop"]'::jsonb, '["potatoes","chickpeas","onion","spinach","oil","stovetop","breakfast"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Хаш с нахут и картофи за закуска","description":"Хрупкави пържени картофи с нахут, лук и спанак","instructions":["Нарежете картофите на кубчета от 1 см, а лука на кубчета","Загрейте олиото в широк тиган и пържете картофите на среден огън 12–15 минути, като ги обръщате от време на време, докато станат златисти и меки","Добавете лука, отцедения нахут, червения пипер, сол и пипер и гответе още 4 минути","Добавете спанака, бъркайте, докато омекне, и поднесете горещо"],"seasonings":["1/2 ч.л. пушен червен пипер","сол","черен пипер"]},"nl":{"name":"Ontbijthash met kikkererwten en aardappel","description":"Knapperig gebakken aardappelen met kikkererwten, ui en spinazie","instructions":["Snijd de aardappelen in blokjes van 1 cm en de ui in blokjes","Verhit de olie in een brede pan en bak de aardappelen 12 tot 15 minuten op middelhoog vuur goudbruin en gaar; keer ze af en toe","Voeg de ui, de uitgelekte kikkererwten, het paprikapoeder, zout en peper toe en bak nog 4 minuten","Roer de spinazie erdoor tot hij slinkt en serveer warm"],"seasonings":["1/2 tl gerookt paprikapoeder","zout","zwarte peper"]}}'::jsonb, 13),
  ('b-shakshuka', 'Shakshuka', 'Eggs poached in a spiced tomato and pepper sauce', 'breakfast', 'eggs', '🍅', 25, 'balanced', 342, 18, 23, 21, 8, 13, 451, '[{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"chopped tomatoes","amount":250,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"onion","amount":60,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","pinch of chili flakes","salt","black pepper"]'::jsonb, '["Slice the onion and pepper and finely chop the garlic","Heat the olive oil in a small pan and soften the onion and pepper for 5 minutes, then add the garlic and spices for 1 minute","Pour in the chopped tomatoes, season and simmer for 8 to 10 minutes until slightly thickened","Make {n:eggs} wells in the sauce, crack in the eggs, cover and cook 4 to 5 minutes until the whites are set"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","spicy","comfort","light","eggs","chopped tomatoes","peppers","onion","garlic","olive oil","stovetop","breakfast"]'::jsonb, '["vegetarian","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Шакшука","description":"Яйца, сготвени в пикантен сос от домати и чушки","instructions":["Нарежете лука и чушката на ивици и накълцайте чесъна на ситно","Загрейте зехтина в малък тиган и задушете лука и чушката за 5 минути, след което добавете чесъна и подправките за 1 минута","Изсипете нарязаните домати, овкусете и варете на тих огън 8–10 минути, докато сосът леко се сгъсти","Направете {n:eggs} гнезда в соса, чукнете яйцата в тях, покрийте и гответе 4–5 минути, докато белтъкът стегне"],"seasonings":["1 ч.л. смлян кимион","1 ч.л. червен пипер","щипка люспи чили","сол","черен пипер"]},"nl":{"name":"Shakshuka","description":"Eieren gepocheerd in een gekruide saus van tomaat en paprika","instructions":["Snijd de ui en de paprika in reepjes en hak de knoflook fijn","Verhit de olijfolie in een kleine pan en bak de ui en de paprika 5 minuten zacht; voeg dan de knoflook en de kruiden 1 minuut toe","Giet de tomatenblokjes erbij, breng op smaak en laat 8 tot 10 minuten zachtjes koken tot de saus iets dikker is","Maak {n:eggs} kuiltjes in de saus, breek de eieren erin, dek af en laat 4 tot 5 minuten garen tot het eiwit gestold is"],"seasonings":["1 tl gemalen komijn","1 tl paprikapoeder","snufje chilivlokken","zout","zwarte peper"]}}'::jsonb, 14),
  ('b-cottage-cheese-apple-bowl', 'Cottage Cheese Bowl with Apple and Honey', 'High-protein cottage cheese with crisp apple, honey and cinnamon', 'breakfast', 'cottage cheese', '🍏', 5, 'quick', 320, 23, 40, 9, 4, 32, 632, '[{"name":"cottage cheese","amount":200,"unit":"g"},{"name":"apple","amount":1,"unit":"","label":"1 apple"},{"name":"honey","amount":10,"unit":"g"}]'::jsonb, '["pinch of cinnamon"]'::jsonb, '["Spoon the cottage cheese into a bowl","Core the apple and cut it into thin slices or small cubes","Top the cottage cheese with the apple, drizzle with honey and dust with cinnamon"]'::jsonb, '[]'::jsonb, '["fresh","quick","light","cottage cheese","apple","honey","breakfast"]'::jsonb, '["vegetarian","gluten-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Купа котидж сирене с ябълка и мед","description":"Богато на протеин котидж сирене с хрупкава ябълка, мед и канела","instructions":["Сипете котидж сиренето в купа","Почистете ябълката от семките и я нарежете на тънки резени или малки кубчета","Сложете ябълката върху сиренето, полейте с мед и поръсете с канела"],"seasonings":["щипка канела"]},"nl":{"name":"Hüttenkäse met appel en honing","description":"Eiwitrijke hüttenkäse met knapperige appel, honing en kaneel","instructions":["Schep de hüttenkäse in een kom","Verwijder het klokhuis van de appel en snijd hem in dunne plakjes of kleine blokjes","Leg de appel op de hüttenkäse, besprenkel met honing en bestrooi met kaneel"],"seasonings":["snufje kaneel"]}}'::jsonb, 15),
  ('b-pancakes-strawberries', 'Pancakes with Strawberries', 'Thin homemade pancakes with fresh strawberries and honey', 'breakfast', 'flour', '🥞', 25, 'balanced', 508, 18, 72, 17, 4, 24, 203, '[{"name":"flour","amount":60,"unit":"g"},{"name":"eggs","amount":1,"unit":"","label":"1 egg"},{"name":"milk","amount":120,"unit":"ml"},{"name":"butter","amount":10,"unit":"g"},{"name":"strawberries","amount":100,"unit":"g"},{"name":"honey","amount":15,"unit":"g"}]'::jsonb, '["pinch of salt"]'::jsonb, '["Whisk the flour, egg, milk and salt into a smooth batter and let it rest for 5 minutes","Melt a little of the butter in a non-stick pan over medium heat","Pour in a thin layer of batter, cook about 1 minute per side until golden, and repeat with the rest of the batter","Slice the strawberries and serve the pancakes topped with them and the honey"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","flour","eggs","milk","butter","strawberries","honey","stovetop","breakfast"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Палачинки с ягоди","description":"Тънки домашни палачинки с пресни ягоди и мед","instructions":["Разбийте брашното, яйцето, млякото и солта на гладко тесто и го оставете да почине 5 минути","Разтопете малко от маслото в незалепващ тиган на среден огън","Изсипете тънък слой тесто, печете около 1 минута от всяка страна до златисто и повторете с останалото тесто","Нарежете ягодите на резенчета и поднесете палачинките с тях и с меда"],"seasonings":["щипка сол"]},"nl":{"name":"Pannenkoeken met aardbeien","description":"Dunne zelfgemaakte pannenkoeken met verse aardbeien en honing","instructions":["Klop de bloem, het ei, de melk en het zout tot een glad beslag en laat het 5 minuten rusten","Smelt een beetje van de boter in een koekenpan met antiaanbaklaag op middelhoog vuur","Giet er een dun laagje beslag in, bak ongeveer 1 minuut per kant goudbruin en herhaal met de rest van het beslag","Snijd de aardbeien in plakjes en serveer de pannenkoeken met de aardbeien en de honing erop"],"seasonings":["snufje zout"]}}'::jsonb, 16),
  ('b-banana-egg-pancakes', 'Banana Egg Pancakes', 'Flourless two-ingredient pancakes with blueberries', 'breakfast', 'eggs', '🥞', 12, 'quick', 343, 16, 37, 16, 5, 21, 158, '[{"name":"banana","amount":1,"unit":"","label":"1 banana"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"blueberries","amount":60,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["pinch of cinnamon"]'::jsonb, '["Mash the banana very smooth in a bowl, then whisk in the eggs and cinnamon","Heat the oil in a non-stick pan over medium-low heat","Drop in small spoonfuls of batter and cook about 2 minutes per side, turning carefully","Serve topped with the blueberries"]'::jsonb, '["stovetop"]'::jsonb, '["quick","light","banana","eggs","blueberries","oil","stovetop","breakfast"]'::jsonb, '["vegetarian","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Палачинки от банан и яйца","description":"Палачинки без брашно от две съставки, с боровинки","instructions":["Намачкайте банана много гладко в купа, след което добавете яйцата и канелата и разбийте","Загрейте олиото в незалепващ тиган на умерено слаб огън","Сипвайте по малко от сместа с лъжица и печете около 2 минути от всяка страна, като обръщате внимателно","Поднесете с боровинките отгоре"],"seasonings":["щипка канела"]},"nl":{"name":"Pannenkoekjes van banaan en ei","description":"Pannenkoekjes zonder bloem van twee ingrediënten, met blauwe bessen","instructions":["Prak de banaan heel fijn in een kom en klop de eieren en de kaneel erdoor","Verhit de olie in een koekenpan met antiaanbaklaag op middelmatig tot laag vuur","Schep kleine lepels beslag in de pan en bak ongeveer 2 minuten per kant; keer voorzichtig","Serveer met de blauwe bessen erop"],"seasonings":["snufje kaneel"]}}'::jsonb, 17),
  ('b-breakfast-burrito', 'Breakfast Burrito', 'A warm tortilla filled with scrambled eggs, beans, cheese and tomato', 'breakfast', 'eggs', '🌯', 12, 'quick', 559, 30, 46, 28, 6, 7, 944, '[{"name":"tortilla","amount":1,"unit":"","label":"1 tortilla"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"kidney beans","amount":60,"unit":"g"},{"name":"cheese","amount":25,"unit":"g"},{"name":"tomato","amount":60,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["pinch of ground cumin","salt","black pepper"]'::jsonb, '["Dice the tomato, grate the cheese and drain the beans","Heat the oil in a pan, warm the beans with the cumin for 1 minute, then pour in the beaten eggs and scramble until just set","Warm the tortilla in a dry pan for 20 seconds per side","Fill it with the eggs and beans, cheese and tomato, fold in the sides and roll up"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","quick","hearty","tortilla","eggs","kidney beans","cheese","tomato","oil","stovetop","breakfast"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Бурито за закуска","description":"Топла тортила с бъркани яйца, боб, кашкавал и домат","instructions":["Нарежете домата на кубчета, настържете кашкавала и отцедете боба","Загрейте олиото в тиган, затоплете боба с кимиона за 1 минута, след което изсипете разбитите яйца и бъркайте, докато едва стегнат","Затоплете тортилата в сух тиган по 20 секунди от всяка страна","Напълнете я с яйцата и боба, кашкавала и домата, подгънете краищата и навийте"],"seasonings":["щипка смлян кимион","сол","черен пипер"]},"nl":{"name":"Ontbijtburrito","description":"Een warme tortilla gevuld met roerei, bonen, kaas en tomaat","instructions":["Snijd de tomaat in blokjes, rasp de kaas en laat de bonen uitlekken","Verhit de olie in een pan, verwarm de bonen 1 minuut met de komijn, giet dan de losgeklopte eieren erbij en roer tot ze net gestold zijn","Verwarm de tortilla 20 seconden per kant in een droge pan","Vul hem met de eieren en bonen, de kaas en de tomaat, vouw de zijkanten naar binnen en rol op"],"seasonings":["snufje gemalen komijn","zout","zwarte peper"]}}'::jsonb, 18),
  ('b-sweet-potato-bean-hash', 'Sweet Potato and Bean Hash', 'Pan-fried sweet potato with kidney beans, peppers and onion', 'breakfast', 'sweet potato', '🍠', 25, 'balanced', 420, 12, 70, 12, 14, 17, 346, '[{"name":"sweet potato","amount":200,"unit":"g"},{"name":"kidney beans","amount":100,"unit":"g"},{"name":"peppers","amount":60,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["1/2 tsp ground cumin","1/2 tsp smoked paprika","salt","black pepper"]'::jsonb, '["Peel the sweet potato and cut it into 1 cm cubes; dice the onion and pepper","Heat the olive oil in a wide pan and fry the sweet potato over medium heat for 10 to 12 minutes until tender and browned","Add the onion, pepper and spices and cook 4 more minutes","Stir in the drained beans, heat through for 2 minutes and season to taste"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","sweet potato","kidney beans","peppers","onion","olive oil","stovetop","breakfast"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Хаш със сладък картоф и боб","description":"Пържен сладък картоф с червен боб, чушка и лук","instructions":["Обелете сладкия картоф и го нарежете на кубчета от 1 см; нарежете лука и чушката на кубчета","Загрейте зехтина в широк тиган и пържете сладкия картоф на среден огън 10–12 минути, докато омекне и се зачерви","Добавете лука, чушката и подправките и гответе още 4 минути","Добавете отцедения боб, затоплете 2 минути и овкусете"],"seasonings":["1/2 ч.л. смлян кимион","1/2 ч.л. пушен червен пипер","сол","черен пипер"]},"nl":{"name":"Hash van zoete aardappel en bonen","description":"Gebakken zoete aardappel met kidneybonen, paprika en ui","instructions":["Schil de zoete aardappel en snijd hem in blokjes van 1 cm; snijd de ui en de paprika in blokjes","Verhit de olijfolie in een brede pan en bak de zoete aardappel 10 tot 12 minuten op middelhoog vuur gaar en bruin","Voeg de ui, de paprika en de kruiden toe en bak nog 4 minuten","Roer de uitgelekte bonen erdoor, verwarm 2 minuten mee en breng op smaak"],"seasonings":["1/2 tl gemalen komijn","1/2 tl gerookt paprikapoeder","zout","zwarte peper"]}}'::jsonb, 19),
  ('b-spicy-egg-avocado-taco', 'Spicy Egg and Avocado Breakfast Taco', 'Tortilla with chili scrambled eggs, avocado and tomato', 'breakfast', 'eggs', '🌮', 10, 'quick', 620, 22, 45, 41, 12, 5, 611, '[{"name":"tortilla","amount":1,"unit":"","label":"1 tortilla"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"tomato","amount":60,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1/2 tsp chili flakes","salt","squeeze of lime juice"]'::jsonb, '["Beat the eggs with the chili flakes and salt and scramble them in the oil over medium heat for 2 minutes","Mash the avocado with lime juice and a pinch of salt","Warm the tortilla in a dry pan, spread with the avocado and top with the eggs and diced tomato"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","spicy","quick","hearty","tortilla","eggs","avocado","tomato","oil","stovetop","breakfast"]'::jsonb, '["vegetarian","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Пикантно тако с яйца и авокадо за закуска","description":"Тортила с бъркани яйца с чили, авокадо и домат","instructions":["Разбийте яйцата с люспите чили и сол и ги бъркайте в олиото на среден огън 2 минути","Намачкайте авокадото със сок от лайм и щипка сол","Затоплете тортилата в сух тиган, намажете я с авокадото и сложете отгоре яйцата и нарязания на кубчета домат"],"seasonings":["1/2 ч.л. люспи чили","сол","няколко капки сок от лайм"]},"nl":{"name":"Pittige ontbijttaco met ei en avocado","description":"Tortilla met roerei met chili, avocado en tomaat","instructions":["Klop de eieren los met de chilivlokken en zout en roerbak ze 2 minuten in de olie op middelhoog vuur","Prak de avocado met limoensap en een snufje zout","Verwarm de tortilla in een droge pan, besmeer met de avocado en leg de eieren en de tomatenblokjes erop"],"seasonings":["1/2 tl chilivlokken","zout","kneepje limoensap"]}}'::jsonb, 20),
  ('b-chili-scrambled-eggs-toast', 'Chili Scrambled Eggs on Toast', 'Soft scrambled eggs with chili and tomato on buttered toast', 'breakfast', 'eggs', '🌶️', 8, 'quick', 463, 30, 34, 22, 5, 6, 589, '[{"name":"eggs","amount":3,"unit":"","label":"3 eggs"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"butter","amount":5,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"}]'::jsonb, '["1/2 tsp chili flakes","salt"]'::jsonb, '["Beat the eggs with the chili flakes and salt","Melt the butter in a pan over medium-low heat, add the diced tomato for 1 minute, then pour in the eggs","Stir gently for 2 to 3 minutes until softly set","Pile onto the toasted bread"]'::jsonb, '["stovetop"]'::jsonb, '["spicy","quick","eggs","bread","butter","tomato","stovetop","breakfast"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Бъркани яйца с чили върху препечен хляб","description":"Меки бъркани яйца с чили и домат върху филийка с масло","instructions":["Разбийте яйцата с люспите чили и сол","Разтопете маслото в тиган на умерено слаб огън, добавете нарязания на кубчета домат за 1 минута и изсипете яйцата","Бъркайте леко 2–3 минути, докато стегнат меко","Сложете върху препечения хляб"],"seasonings":["1/2 ч.л. люспи чили","сол"]},"nl":{"name":"Roerei met chili op toast","description":"Zacht roerei met chili en tomaat op beboterde toast","instructions":["Klop de eieren los met de chilivlokken en zout","Smelt de boter in een pan op middelmatig tot laag vuur, bak de tomatenblokjes 1 minuut en giet dan de eieren erbij","Roer 2 tot 3 minuten voorzichtig tot het ei zacht gestold is","Schep op het geroosterde brood"],"seasonings":["1/2 tl chilivlokken","zout"]}}'::jsonb, 21),
  ('b-spicy-tofu-bean-wrap', 'Spicy Tofu and Bean Breakfast Wrap', 'Tortilla with chili tofu scramble, kidney beans and peppers', 'breakfast', 'tofu', '🌯', 12, 'quick', 488, 31, 49, 21, 9, 7, 599, '[{"name":"tofu","amount":120,"unit":"g"},{"name":"tortilla","amount":1,"unit":"","label":"1 tortilla"},{"name":"kidney beans","amount":60,"unit":"g"},{"name":"peppers","amount":50,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1/2 tsp chili flakes","1/2 tsp ground cumin","1/2 tsp turmeric","salt"]'::jsonb, '["Dice the peppers and cook them in the oil for 2 minutes","Crumble in the tofu with the chili flakes, cumin, turmeric and salt and cook for 4 minutes","Add the drained kidney beans and heat through","Warm the tortilla, add the filling and roll up"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","spicy","quick","tofu","tortilla","kidney beans","peppers","oil","stovetop","breakfast"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Пикантен врап с тофу и боб за закуска","description":"Тортила с бъркано тофу с чили, червен боб и чушка","instructions":["Нарежете чушката на кубчета и я запържете в олиото за 2 минути","Натрошете тофуто, добавете люспите чили, кимиона, куркумата и сол и гответе 4 минути","Добавете отцедения червен боб и го затоплете","Затоплете тортилата, сложете плънката и навийте"],"seasonings":["1/2 ч.л. люспи чили","1/2 ч.л. смлян кимион","1/2 ч.л. куркума","сол"]},"nl":{"name":"Pittige ontbijtwrap met tofu en bonen","description":"Tortilla met roertofu met chili, kidneybonen en paprika","instructions":["Snijd de paprika in blokjes en bak ze 2 minuten in de olie","Verkruimel de tofu erboven, voeg de chilivlokken, de komijn, de kurkuma en zout toe en bak 4 minuten","Voeg de uitgelekte kidneybonen toe en warm ze goed door","Verwarm de tortilla, leg de vulling erop en rol op"],"seasonings":["1/2 tl chilivlokken","1/2 tl gemalen komijn","1/2 tl kurkuma","zout"]}}'::jsonb, 22),
  ('b-harissa-chickpeas-toast', 'Harissa Chickpeas on Toast', 'Warm spiced chickpeas with tomato and spinach on toast', 'breakfast', 'chickpeas', '🌶️', 10, 'quick', 441, 19, 62, 14, 14, 11, 650, '[{"name":"chickpeas","amount":120,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"tomato","amount":100,"unit":"g"},{"name":"spinach","amount":40,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp harissa paste","salt","squeeze of lemon juice"]'::jsonb, '["Warm the olive oil in a pan and cook the diced tomato with the harissa for 2 minutes","Add the drained chickpeas and cook for 3 minutes, lightly crushing some of them","Stir in the spinach until wilted and season with salt and lemon juice","Spoon over the toasted bread"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","spicy","quick","chickpeas","bread","tomato","spinach","olive oil","stovetop","breakfast"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Нахут с хариса върху препечен хляб","description":"Топъл пикантен нахут с домат и спанак върху филийка","instructions":["Затоплете зехтина в тиган и гответе нарязания на кубчета домат с харисата за 2 минути","Добавете отцедения нахут и гответе 3 минути, като леко намачкате част от него","Добавете спанака, бъркайте, докато омекне, и овкусете със сол и лимонов сок","Сложете върху препечения хляб"],"seasonings":["1 ч.л. хариса","сол","няколко капки лимонов сок"]},"nl":{"name":"Kikkererwten met harissa op toast","description":"Warme gekruide kikkererwten met tomaat en spinazie op toast","instructions":["Verwarm de olijfolie in een pan en bak de tomatenblokjes 2 minuten met de harissa","Voeg de uitgelekte kikkererwten toe en bak 3 minuten; plet er een paar licht","Roer de spinazie erdoor tot hij geslonken is en breng op smaak met zout en citroensap","Schep over het geroosterde brood"],"seasonings":["1 tl harissa","zout","kneepje citroensap"]}}'::jsonb, 23),
  ('b-menemen', 'Menemen', 'Turkish eggs scrambled into soft tomatoes and peppers, with bread', 'breakfast', 'eggs', '🍅', 15, 'quick', 481, 28, 31, 28, 7, 12, 408, '[{"name":"eggs","amount":3,"unit":"","label":"3 eggs"},{"name":"tomato","amount":200,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"onion","amount":30,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"},{"name":"bread","amount":35,"unit":"g","label":"1 slice"}]'::jsonb, '["1/2 tsp chili flakes","1/2 tsp paprika","salt"]'::jsonb, '["Dice the onion and peppers and soften them in the olive oil for 4 minutes","Add the chopped tomato, chili flakes, paprika and salt and cook for 5 minutes until saucy","Pour in the lightly beaten eggs and stir gently for 2 minutes until just set","Serve from the pan with the bread"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","spicy","quick","eggs","tomato","peppers","onion","olive oil","bread","stovetop","breakfast"]'::jsonb, '["vegetarian","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Менемен","description":"Яйца по турски, забъркани в меки домати и чушки, с хляб","instructions":["Нарежете лука и чушките на кубчета и ги задушете в зехтина за 4 минути","Добавете нарязания домат, люспите чили, червения пипер и сол и гответе 5 минути, докато се получи сос","Изсипете леко разбитите яйца и бъркайте внимателно 2 минути, докато едва стегнат","Поднесете в тигана с хляба"],"seasonings":["1/2 ч.л. люспи чили","1/2 ч.л. червен пипер","сол"]},"nl":{"name":"Menemen","description":"Turks roerei in zachte tomaat en paprika, met brood","instructions":["Snijd de ui en de paprika in blokjes en bak ze 4 minuten zacht in de olijfolie","Voeg de gehakte tomaat, de chilivlokken, het paprikapoeder en zout toe en bak 5 minuten tot het sauzig is","Giet de licht losgeklopte eieren erbij en roer 2 minuten voorzichtig tot ze net gestold zijn","Serveer uit de pan met het brood"],"seasonings":["1/2 tl chilivlokken","1/2 tl paprikapoeder","zout"]}}'::jsonb, 