  ('l-turkey-taco-salad', 'Turkey Taco Salad', 'Spiced turkey mince over lettuce with tomato, corn, beans and avocado', 'lunch', 'turkey mince', '🥗', 15, 'quick', 607, 36, 40, 37, 17, 9, 358, '[{"name":"turkey mince","amount":130,"unit":"g"},{"name":"lettuce","amount":80,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"corn","amount":60,"unit":"g"},{"name":"kidney beans","amount":60,"unit":"g"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","salt","squeeze of lime juice"]'::jsonb, '["Brown the turkey mince in the oil over high heat for 6 minutes with the cumin, paprika and salt","Shred the lettuce and dice the tomato and avocado","Arrange the lettuce in a bowl and top with the turkey, tomato, corn, drained kidney beans and avocado","Squeeze over lime juice"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","fresh","quick","turkey mince","lettuce","tomato","corn","kidney beans","avocado","oil","stovetop","lunch"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Тако салата с пуешка кайма","description":"Пуешка кайма с подправки върху маруля с домат, царевица, боб и авокадо","instructions":["Запържете пуешката кайма в олиото на силен огън за 6 минути с кимиона, червения пипер и сол","Нарежете марулята на ивици, а домата и авокадото на кубчета","Подредете марулята в купа и сложете отгоре каймата, домата, царевицата, отцедения червен боб и авокадото","Изстискайте сок от лайм"],"seasonings":["1 ч.л. смлян кимион","1 ч.л. червен пипер","сол","няколко капки сок от лайм"]},"nl":{"name":"Tacosalade met kalkoen","description":"Gekruid kalkoengehakt op sla met tomaat, mais, bonen en avocado","instructions":["Bak het kalkoengehakt 6 minuten bruin in de olie op hoog vuur met de komijn, het paprikapoeder en zout","Snijd de sla in reepjes en de tomaat en de avocado in blokjes","Leg de sla in een kom en verdeel het gehakt, de toma