  ('l-minestrone', 'Minestrone', 'Chunky vegetable and bean soup with pasta and parmesan', 'lunch', 'kidney beans', '🥣', 30, 'balanced', 444, 19, 66, 13, 13, 16, 584, '[{"name":"kidney beans","amount":80,"unit":"g"},{"name":"pasta","amount":40,"unit":"g"},{"name":"carrots","amount":60,"unit":"g"},{"name":"zucchini","amount":80,"unit":"g"},{"name":"chopped tomatoes","amount":200,"unit":"g"},{"name":"onion","amount":40,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"},{"name":"parmesan","amount":10,"unit":"g"}]'::jsonb, '["1 stock cube","{400} ml water","1 tsp dried oregano","black pepper"]'::jsonb, '["Dice the onion, carrots and zucchini and soften them in the olive oil in a pot for 5 minutes","Add the chopped tomatoes, water, stock cube and oregano and simmer for 10 minutes","Add the pasta and drained kidney beans and cook for 8 to 10 minutes until the pasta is tender","Serve topped with the grated parmesan and black pepper"]'::jsonb, '["stovetop"]'::jsonb, '["italian","comfort","light","kidney beans","pasta","carrots","zucchini","chopped tomatoes","onion","olive oil","parmesan","stovetop","lunch"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Минестроне","description":"Гъста супа от зеленчуци и боб с паста и пармезан","instructions":["Нарежете лука, морковите и тиквичката на кубчета и ги задушете в зехтина в тенджера за 5 минути","Добавете нарязаните домати, водата, кубчето бульон и ригана и варете на тих огън 10 минути","Добавете пастата и отцедения червен боб и варете 8–10 минути, докато пастата омекне","Поднесете с настъргания пармезан и черен пипер отгоре"],"seasonings":["1 кубче бульон","{400} мл вода","1 ч.л. сух риган","черен пипер"]},"nl":{"name":"Minestrone","description":"Stevige soep van groenten en bonen met pasta en Parmezaanse kaas","instructions":["Snijd de ui, de wortels en de courgette in blokjes en bak ze 5 minuten zacht in de olijfolie in een pan","Voeg de tomatenblokjes, het water, het bouillonblokje en de