  ('l-chicken-pesto-pasta', 'Chicken Pesto Pasta', 'Pasta with pan-fried chicken, pesto, spinach and tomato', 'lunch', 'chicken', '🍝', 20, 'quick', 536, 40, 59, 15, 5, 5, 351, '[{"name":"chicken","amount":120,"unit":"g"},{"name":"pasta","amount":70,"unit":"g"},{"name":"pesto","amount":25,"unit":"g"},{"name":"spinach","amount":50,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Cook the pasta in salted boiling water according to the packet and drain, keeping a little of the water","Cut the chicken into strips, season and fry in a non-stick pan over medium-high heat for 6 minutes until golden","Add the diced tomato and spinach and cook for 1 minute until the spinach wilts","Toss in the pasta, pesto and a splash of the pasta water"]'::jsonb, '["stovetop"]'::jsonb, '["italian","quick","light","chicken","pasta","pesto","spinach","tomato","stovetop","lunch"]'::jsonb, '["halal"]'::jsonb, '{"bg":{"name":"Паста с пилешко и песто","description":"Паста със запържено пилешко, песто, спанак и домат","instructions":["Сварете пастата в подсолена вряща вода според указанията на опаковката и я отцедете, като запазите малко от водата","Нарежете пилешкото на ивици, овкусете го и го запържете в незалепващ тиган на умерено силен огън за 6 минути до златисто","Добавете нарязания на кубчета домат и спанака и гответе 1 минута, докато спанакът омекне","Добавете пастата, пестото и малко от водата от пастата и разбъркайте"],"seasonings":["сол","черен пипер"]},"nl":{"name":"Pasta met kip en pesto","description":"Pasta met gebakken kip, pesto, spinazie en tomaat","instructions":["Kook de pasta in kokend water met zout volgens de verpakking en giet af; bewaar een beetje kookvocht","Snijd de kip in reepjes, kruid ze en bak ze 6 minuten in een koekenpan met antiaanbaklaag op middelhoog tot hoog vuur goudbruin","Voeg de tomatenblokjes en de spinazie toe en bak 1 minuut tot de spinazie slinkt","Schep de pasta, de pesto en een scheutje kookvocht erdoor"],"seasonings":["zout","zwarte peper"]}}'::jsonb, 184),
  ('l-spinach-mushroom-frittata', 'Spinach and Mushroom Frittata', 'Thick Italian omelette with mushrooms, spinach and parmesan, with bread', 'lunch', 'eggs', '🍳', 20, 'quick', 497, 35, 24, 29, 5, 5, 623, '[{"name":"eggs","amount":3,"unit":"","label":"3 eggs"},{"name":"spinach","amount":60,"unit":"g"},{"name":"mushrooms","amount":80,"unit":"g"},{"name":"parmesan","amount":15,"unit":"g"},{"name":"onion","amount":30,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"},{"name":"bread","amount":35,"unit":"g","label":"1 slice"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Slice the mushrooms and onion and fry them in the olive oil in a small non-stick pan for 5 minutes","Add the spinach and let it wilt","Beat the eggs with the grated parmesan, salt and pepper, pour over the vegetables and cook over low heat, covered, for 6 to 8 minutes until set","Slide onto a plate and serve with the bread"]'::jsonb, '["stovetop"]'::jsonb, '["italian","quick","light","eggs","spinach","mushrooms","parmesan","onion","olive oil","bread","stovetop","lunch"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Фритата със спанак и гъби","description":"Дебел италиански омлет с гъби, спанак и пармезан, с хляб","instructions":["Нарежете гъбите и лука на филийки и ги запържете в зехтина в малък незалепващ тиган за 5 минути","Добавете спанака и го оставете да омекне","Разбийте яйцата с настъргания пармезан, сол и пипер, залейте зеленчуците и гответе на слаб огън под капак 6–8 минути, докато стегне","Плъзнете в чиния и поднесете с хляба"],"seasonings":["сол","черен пипер"]},"nl":{"name":"Frittata met spinazie en champignons","description":"Dikke Italiaanse omelet met champignons, spinazie en Parmezaanse kaas, met brood","instructions":["Snijd de champignons en de ui in plakjes en bak ze 5 minuten in de olijfolie in een kleine koekenpan met antiaanbaklaag","Voeg de spinazie toe en laat hem slinken","Klop de eieren los met de geraspte Parmezaanse kaas, zout en peper, 