  ('l-pasta-e-ceci', 'Pasta e Ceci', 'Thick Italian chickpea and pasta soup with tomato and garlic', 'lunch', 'chickpeas', '🥣', 25, 'balanced', 509, 17, 80, 15, 14, 14, 501, '[{"name":"chickpeas","amount":120,"unit":"g"},{"name":"pasta","amount":50,"unit":"g"},{"name":"chopped tomatoes","amount":150,"unit":"g"},{"name":"onion","amount":40,"unit":"g"},{"name":"carrots","amount":40,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["1 stock cube","{350} ml water","1 tsp dried rosemary","black pepper"]'::jsonb, '["Finely dice the onion and carrots and soften them in the olive oil for 5 minutes, then add the chopped garlic and rosemary","Add the chopped tomatoes, water, stock cube and drained chickpeas and simmer for 8 minutes","Crush some of the chickpeas against the side of the pot to thicken the soup","Add the pasta and cook for 8 to 10 minutes, stirring, until tender, then season with pepper"]'::jsonb, '["stovetop"]'::jsonb, '["italian","comfort","light","chickpeas","pasta","chopped tomatoes","onion","carrots","garlic","olive oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Паста е чечи","description":"Гъста италианска супа от нахут и паста с домати и чесън","instructions":["Нарежете лука и морковите на ситни кубчета и ги задушете в зехтина за 5 минути, след което добавете накълцания чесън и розмарина","Добавете нарязаните домати, водата, кубчето бульон и отцедения нахут и варете на тих огън 8 минути","Намачкайте част от нахута в стената на тенджерата, за да се сгъсти супата","Добавете пастата и варете 8–10 минути, като бъркате, докато омекне, след което овкусете с пипер"],"seasonings":["1 кубче бульон","{350} мл вода","1 ч.л. сух розмарин","черен пипер"]},"nl":{"name":"Pasta e ceci","description":"Dikke Italiaanse soep van kikkererwten en pasta met tomaat en knoflook","instructions":["Snijd de ui en de wortels in 