  ('l-salmon-pesto-pasta', 'Salmon and Pea Pesto Pasta', 'Pasta with flaked salmon, peas and pesto', 'lunch', 'salmon', '🐟', 20, 'quick', 594, 34, 57, 24, 5, 5, 322, '[{"name":"salmon","amount":110,"unit":"g"},{"name":"pasta","amount":65,"unit":"g"},{"name":"pesto","amount":20,"unit":"g"},{"name":"peas","amount":50,"unit":"g"}]'::jsonb, '["salt","black pepper","squeeze of lemon juice"]'::jsonb, '["Cook the pasta in salted boiling water according to the packet, adding the peas for the last 2 minutes, then drain","Fry the salmon in a non-stick pan over medium heat for 3 to 4 minutes per side, then break it into flakes","Toss the pasta and peas with the pesto and fold in the salmon","Season with pepper and lemon juice"]'::jsonb, '["stovetop"]'::jsonb, '["italian","quick","salmon","pasta","pesto","peas","stovetop","lunch"]'::jsonb, '["halal","kosher"]'::jsonb, '{"bg":{"name":"Паста с песто, сьомга и грах","description":"Паста с парченца сьомга, грах и песто","instructions":["Сварете пастата в подсолена вряща вода според указанията на опаковката, като през последните 2 минути добавите граха, и отцедете","Изпържете сьомгата в незалепващ тиган на среден огън по 3–4 минути от всяка страна, след което я разделете на парченца","Разбъркайте пастата и граха с пестото и добавете внимателно сьомгата","Овкусете с пипер и лимонов сок"],"seasonings":["сол","черен пипер","няколко капки лимонов сок"]},"nl":{"name":"Pestopasta met zalm en doperwten","description":"Pasta met stukjes zalm, doperwten en pesto","instructions":["Kook de pasta in kokend water met zout volgens de verpakking, kook de doperwten de laatste 2 minuten mee en giet af","Bak de zalm 3 tot 4 minuten per kant in een koekenpan met antiaanbaklaag op middelhoog vuur en trek hem dan in stukjes","Meng de pasta en de doperwten met de pesto en schep de zalm erdoor","Breng op smaak met peper en citroensap"],"seasonings":["zout","zwarte peper","kneepje citroensap"]}}'::jsonb, 189),
  ('l-roasted-vegetable-chickpea-pasta', 'Vegetable and Chickpea Pasta', 'Pasta with zucchini, peppers and chickpeas in tomato sauce', 'lunch', 'chickpeas', '🍝', 25, 'balanced', 534, 19, 90, 13, 13, 17, 295, '[{"name":"chickpeas","amount":100,"unit":"g"},{"name":"pasta","amount":65,"unit":"g"},{"name":"zucchini","amount":100,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"tomato sauce","amount":120,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","salt","black pepper"]'::jsonb, '["Cook the pasta in salted boiling water according to the packet and drain","Dice the zucchini and peppers and fry them in the olive oil over medium-high heat for 7 minutes until soft and browned","Add the drained chickpeas, tomato sauce and oregano and simmer for 5 minutes","Toss with the pasta and season"]'::jsonb, '["stovetop"]'::jsonb, '["italian","light","chickpeas","pasta","zucchini","peppers","tomato sauce","olive oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Паста със зеленчуци и нахут","description":"Паста с тиквичка, чушки и нахут в доматен сос","instructions":["Сварете пастата в подсолена вряща вода според указанията на опаковката и я отцедете","Нарежете тиквичката и чушките на кубчета и ги запържете в зехтина на умерено силен огън за 7 минути, докато омекнат и се зачервят","Добавете отцедения нахут, доматения сос и ригана и варете на тих огън 5 минути","Разбъркайте с пастата и овкусете"],"seasonings":["1 ч.л. сух риган","сол","черен пипер"]},"nl":{"name":"Pasta met groenten en kikkererwten","description":"Pasta met courgette, paprika en kikkererwten in tomatensaus","instructions":["Kook de pasta in kokend water met zout volgens de verpakking en giet af","Snijd de courgette en de paprika in blokjes en bak ze 7 minuten in de olijfolie op middelhoog tot hoog vuur zacht en bruin","Voeg de uitgelekte kikkererwten, de tomatensaus en de oregano toe en l