  ('l-chicken-caprese-salad', 'Chicken Caprese Salad', 'Sliced chicken with mozzarella, tomato, lettuce and pesto', 'lunch', 'chicken', '🥗', 15, 'quick', 479, 45, 10, 28, 3, 5, 511, '[{"name":"chicken","amount":130,"unit":"g"},{"name":"mozzarella","amount":60,"unit":"g"},{"name":"tomato","amount":150,"unit":"g"},{"name":"lettuce","amount":50,"unit":"g"},{"name":"pesto","amount":15,"unit":"g"},{"name":"olive oil","amount":5,"unit":"g"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Season the chicken and fry it in the olive oil over medium heat for 5 to 6 minutes per side until cooked through, then slice","Slice the tomato and mozzarella and arrange them over the lettuce","Top with the chicken and spoon over the pesto"]'::jsonb, '["stovetop"]'::jsonb, '["italian","fresh","quick","light","chicken","mozzarella","tomato","lettuce","pesto","olive oil","stovetop","lunch"]'::jsonb, '["gluten-free","halal"]'::jsonb, '{"bg":{"name":"Салата „Капрезе“ с пилешко","description":"Нарязано пилешко с моцарела, домат, маруля и песто","instructions":["Овкусете пилешкото и го изпържете в зехтина на среден огън по 5–6 минути от всяка страна, докато се сготви, след което го нарежете","Нарежете домата и моцарелата на резени и ги подредете върху марулята","Сложете пилешкото отгоре и полейте с пестото"],"seasonings":["сол","черен пипер"]},"nl":{"name":"Salade caprese met kip","description":"Plakjes kip met mozzarella, tomaat, sla en pesto","instructions":["Kruid de kip en bak hem in de olijfolie op middelhoog vuur 5 tot 6 minuten per kant gaar; snijd hem dan in plakken","Snijd de tomaat en de mozzarella in plakjes en verdeel ze over de sla","Leg de kip erop en schep de pesto erover"],"seasonings":["zout","zwarte peper"]}}'::jsonb, 191),
  ('l-greek-chicken-salad', 'Greek Chicken Salad', 'Grilled chicken over cucumber, tomato and lettuce with feta', 'lunch', 'chicken', '🥗', 15, 'quick', 396, 37, 11, 22, 3, 5, 526, '[{"name":"chicken","amount":130,"unit":"g"},{"name":"feta","amount":40,"unit":"g"},{"name":"cucumber","amount":100,"unit":"g"},{"name":"tomato","amount":120,"unit":"g"},{"name":"lettuce","amount":50,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","squeeze of lemon juice","salt","black pepper"]'::jsonb, '["Season the chicken with the oregano, salt and pepper and fry in half the olive oil over medium heat for 5 to 6 minutes per side, then slice","Chop the cucumber, tomato and lettuce and put them in a bowl","Top with the chicken and crumbled feta and dress with the remaining olive oil and lemon juice"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","fresh","quick","light","chicken","feta","cucumber","tomato","lettuce","olive oil","stovetop","lunch"]'::jsonb, '["gluten-free","nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Гръцка салата с пилешко","description":"Пилешко на тиган върху краставица, домат и маруля с фета","instructions":["Овкусете пилешкото с ригана, сол и пипер и го изпържете в половината зехтин на среден огън по 5–6 минути от всяка страна, след което го нарежете","Нарежете краставицата, домата и марулята и ги сложете в купа","Сложете отгоре пилешкото и натрошената фета и овкусете с останалия зехтин и лимоновия сок"],"seasonings":["1 ч.л. сух риган","няколко капки лимонов сок","сол","черен пипер"]},"nl":{"name":"Griekse salade met kip","description":"Gegrilde kip op komkommer, tomaat en sla met feta","instructions":["Kruid de kip met de oregano, zout en peper en bak hem in de helft van de olijfolie op middelhoog vuur 5 tot 6 minuten per kant; snijd hem dan in plakken","Snijd de komkommer, de tomaat en de sla klein en doe ze in een kom","Leg de kip en de verkruimelde feta erop en maak aan met de rest van de olijfolie en het citroensap"],"seasonings":["1 tl gedroogde oregano","kneepje citroensap","zout","zwarte peper"]}}'::jsonb, 192),
  ('l-chickpea-couscous-salad', 'Chickpea Couscous Salad', 'Lemony couscous with chickpeas, cucumber, tomato and peppers', 'lunch', 'chickpeas', '🍋', 10, 'quick', 544, 19, 89, 14, 15, 13, 312, '[{"name":"chickpeas","amount":120,"unit":"g"},{"name":"couscous","amount":60,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"peppers","amount":60,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["{80} ml boiling water","salt","handful of fresh parsley","1/2 tsp ground cumin"]'::jsonb, '["Put the couscous in a bowl with a pinch of salt, pour over the boiling water, cover and leave for 5 minutes, then fluff with a fork","Dice the cucumber, tomato and peppers","Mix everything with the drained chickpeas, olive oil, the juice of the lemon, cumin and chopped parsley"]'::jsonb, '[]'::jsonb, '["mediterranean","fresh","quick","light","chickpeas","couscous","cucumber","tomato","peppers","olive oil","lemon","lunch"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Салата с кускус и нахут","description":"Кускус с лимон, нахут, краставица, домат и чушки","instructions":["Сложете кускуса в купа с щипка сол, залейте го с врящата вода, покрийте и оставете 5 минути, след което го разрохкайте с вилица","Нарежете краставицата, домата и чушките на кубчета","Смесете всичко с отцедения нахут, зехтина, сока от лимона, кимиона и нарязания магданоз"],"seasonings":["{80} мл вряща вода","сол","шепа пресен магданоз","1/2 ч.л. смлян кимион"]},"nl":{"name":"Couscoussalade met kikkererwten","description":"Couscous met citroen, kikkererwten, komkommer, tomaat en paprika","instructions":["Doe de couscous met een snufje zout in een kom, giet het kokende water erover, dek af en laat 5 minuten staan; maak hem dan los met een vork","Snijd de komkommer, de tomaat en de paprika in blokjes","Meng alles met de uitgelekte kikkererwten, de olijfolie, het sap van de citroen, de komijn en de gehakte peterselie"],"seasonings":["{80} ml kokend water","zout","handje verse peterselie","1/2 tl gemalen komijn"]}}'::jsonb, 193),
  ('l-chickpea-feta-wrap', 'Chickpea and Feta Wrap', 'Tortilla with crushed chickpeas, feta, cucumber, tomato and yogurt', 'lunch', 'chickpeas', '🌯', 10, 'quick', 446, 19, 60, 16, 10, 11, 1052, '[{"name":"tortilla","amount":1,"unit":"","label":"1 tortilla"},{"name":"chickpeas","amount":100,"unit":"g"},{"name":"feta","amount":30,"unit":"g"},{"name":"cucumber","amount":60,"unit":"g"},{"name":"tomato","amount":60,"unit":"g"},{"name":"yogurt","amount":40,"unit":"g"}]'::jsonb, '["1/2 tsp ground cumin","squeeze of lemon juice","black pepper"]'::jsonb, '["Roughly crush the drained chickpeas with a fork and mix them with the yogurt, cumin, lemon juice and pepper","Dice the cucumber and tomato and crumble the feta","Spread the chickpeas over the tortilla, top with the vegetables and feta and roll up tightly"]'::jsonb, '[]'::jsonb, '["mediterranean","fresh","quick","light","tortilla","chickpeas","feta","cucumber","tomato","yogurt","lunch"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Врап с нахут и фета","description":"Тортила с намачкан нахут, фета, краставица, домат и кисело мляко","instructions":["Намачкайте на едро отцедения нахут с вилица и го смесете с киселото мляко, кимиона, лимоновия сок и пипер","Нарежете краставицата и домата на кубчета и натрошете фетата","Намажете нахута върху тортилата, сложете зеленчуците и фетата и навийте стегнато"],"seasonings":["1/2 ч.л. смлян кимион","няколко капки лимонов сок","черен пипер"]},"nl":{"name":"Wrap met kikkererwten en feta","description":"Tortilla met geplette kikkererwten, feta, komkommer, tomaat en yoghurt","instructions":["Plet de uitgelekte kikkererwten grof met een vork en meng ze met de yoghurt, de komijn, het citroensap en peper","Snijd de komkommer en de tomaat in blokjes en verkruimel de feta","Smeer de kikkererwten over de tortilla, leg de groenten en de feta erop en rol strak op"],"seasonings":["1/2 tl gemalen komijn","kneepje citroensap","zwarte peper"]}}'::jsonb, 194),
  ('l-turkish-eggs', 'Turkish Eggs with Garlic Yogurt', 'Poached eggs on garlic yogurt with chili butter and bread', 'lunch', 'eggs', '🍳', 15, 'quick', 557, 36, 38, 29, 4, 9, 592, '[{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"greek yogurt","amount":150,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"butter","amount":10,"unit":"g"},{"name":"garlic","amount":4,"unit":"g","label":"1 clove"}]'::jsonb, '["1/2 tsp chili flakes","1/2 tsp paprika","salt","splash of vinegar"]'::jsonb, '["Stir the finely grated garlic and a pinch of salt into the yogurt and spread it in a shallow bowl","Poach the eggs in barely simmering water with a splash of vinegar for 3 minutes and lift them onto the yogurt","Melt the butter with the chili flakes and paprika until it foams and pour it over the eggs","Serve with the toasted bread"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","spicy","quick","eggs","greek yogurt","bread","butter","garlic","stovetop","lunch"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Яйца по турски с чесново кисело мляко","description":"Поширани яйца върху кисело мляко с чесън, с масло с чили и хляб","instructions":["Разбъркайте ситно настъргания чесън и щипка сол в киселото мляко и го разстелете в плитка купа","Поширайте яйцата за 3 минути в едва къкреща вода с малко оцет и ги прехвърлете върху млякото","Разтопете маслото с люспите чили и червения пипер, докато се запени, и полейте яйцата","Поднесете с препечения хляб"],"seasonings":["1/2 ч.л. люспи чили","1/2 ч.л. червен пипер","сол","малко оцет"]},"nl":{"name":"Turkse eieren met knoflookyoghurt","description":"Gepocheerde eieren op knoflookyoghurt met chiliboter en brood","instructions":["Roer de fijn geraspte knoflook en een snufje zout door de yoghurt en verdeel hem over een diep bord","Pocheer de eieren 3 minuten in net niet kokend water met een scheutje azijn en schep ze op de yoghurt","Smelt de boter met de chilivlokken en