  ('l-tuna-chickpea-salad', 'Tuna and Chickpea Salad', 'No-cook salad of tuna, chickpeas, tomato and cucumber with lemon', 'lunch', 'tuna', '🥗', 10, 'quick', 372, 29, 38, 14, 10, 11, 503, '[{"name":"tuna","amount":100,"unit":"g"},{"name":"chickpeas","amount":100,"unit":"g"},{"name":"tomato","amount":120,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"onion","amount":20,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["salt","black pepper","handful of fresh parsley"]'::jsonb, '["Drain the tuna and chickpeas","Dice the tomato and cucumber and slice the onion very thinly","Toss everything with the olive oil, the juice of the lemon, salt, pepper and chopped parsley"]'::jsonb, '[]'::jsonb, '["mediterranean","fresh","quick","light","tuna","chickpeas","tomato","cucumber","onion","olive oil","lemon","lunch"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Салата с риба тон и нахут","description":"Салата без готвене от риба тон, нахут, домат и краставица с лимон","instructions":["Отцедете рибата тон и нахута","Нарежете домата и краставицата на кубчета, а лука на много тънки резени","Разбъркайте всичко със зехтина, сока от лимона, сол, пипер и нарязания магданоз"],"seasonings":["сол","черен пипер","шепа пресен магданоз"]},"nl":{"name":"Salade met tonijn en kikkererwten","description":"Salade zonder koken van tonijn, kikkererwten, tomaat en komkommer met citroen","instructions":["Laat de tonijn en de kikkererwten uitlekken","Snijd de tomaat en de komkommer in blokjes en de ui in flinterdunne ringen","Meng alles met de olijfolie, het sap van de citroen, zout, peper en de gehakte peterselie"],"seasonings":["zout","zwarte peper","handje verse peterselie"]}}'::jsonb, 196),
  ('l-lemony-lentil-soup', 'Lemony Lentil Soup', 'Smooth-ish lentil and carrot soup with spinach and lemon', 'lunch', 'lentils', '🍋', 30, 'balanced', 419, 22, 68, 10, 15, 11, 205, '[{"name":"lentils","amount":70,"unit":"g"},{"name":"carrots","amount":60,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"chopped tomatoes","amount":100,"unit":"g"},{"name":"spinach","amount":50,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"olive oil","amount":8,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["1 tsp ground cumin","1 stock cube","{450} ml water","black pepper"]'::jsonb, '["Dice the onion and carrots and soften them in the olive oil for 5 minutes, then add the chopped garlic and cumin","Add the rinsed lentils, chopped tomatoes, water and stock cube and simmer for 20 minutes until the lentils are soft","Stir in the spinach until wilted","Add the juice of the lemon and black pepper"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","comfort","light","lentils","carrots","onion","chopped tomatoes","spinach","garlic","olive oil","lemon","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Супа от леща с лимон","description":"Почти гладка супа от леща и моркови със спанак и лимон","instructions":["Нарежете лука и морковите на кубчета и ги задушете в зехтина за 5 минути, след което добавете накълцания чесън и кимиона","Добавете измитата леща, нарязаните домати, водата и кубчето бульон и варете на тих огън 20 минути, докато лещата омекне","Добавете спанака и бъркайте, докато омекне","Добавете сока от лимона и черен пипер"],"seasonings":["1 ч.л. смлян кимион","1 кубче бульон","{450} мл вода","черен пипер"]},"nl":{"name":"Linzensoep met citroen","description":"Vrij gladde soep van linzen en wortel met spinazie en citroen","instructions":["Snijd de ui en de wortels in blokjes en bak ze 5 minuten zacht in de olijfolie; voeg dan de gehakte knoflook en de komijn toe","Voeg de afgespoelde linzen, de tomatenblokjes, het water en het bouillonblokje toe en laat 20 minuten zachtjes koken tot de linzen zacht zijn","Roer de spinazie erdoor tot hij geslonken is","Voeg het sap van de citroen en zwarte peper toe"],"seasonings":["1 tl gemalen komijn","1 bouillonblokje","{450} ml water","zwarte peper"]}}'::jsonb, 197),
  ('l-chicken-gyros-wrap', 'Chicken Gyros Wrap', 'Oregano chicken in a tortilla with yogurt, cucumber, tomato and onion', 'lunch', 'chicken', '🌯', 15, 'quick', 460, 40, 38, 16, 3, 8, 523, '[{"name":"chicken","amount":130,"unit":"g"},{"name":"tortilla","amount":1,"unit":"","label":"1 tortilla"},{"name":"greek yogurt","amount":50,"unit":"g"},{"name":"cucumber","amount":60,"unit":"g"},{"name":"tomato","amount":60,"unit":"g"},{"name":"onion","amount":20,"unit":"g"},{"name":"olive oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","1/2 tsp paprika","salt","squeeze of lemon juice"]'::jsonb, '["Cut the chicken into thin strips, toss with the oregano, paprika and salt and fry in the olive oil over high heat for 5 to 6 minutes","Slice the cucumber, tomato and onion","Warm the tortilla, spread it with the yogurt and fill with the chicken and vegetables","Squeeze over lemon juice and roll up"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","quick","light","chicken","tortilla","greek yogurt","cucumber","tomato","onion","olive oil","stovetop","lunch"]'::jsonb, '["nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Врап с пилешки гирос","description":"Пилешко с риган в тортила с кисело мляко, краставица, домат и лук","instructions":["Нарежете пилешкото на тънки ивици, овкусете го с ригана, червения пипер и сол и го запържете в зехтина на силен огън за 5–6 минути","Нарежете краставицата, домата и лука на резени","Затоплете тортилата, намажете я с киселото мляко и я напълнете с пилешкото и зеленчуците","Изстискайте лимонов сок и навийте"],"seasonings":["1 ч.л. сух риган","1/2 ч.л. червен пипер","сол","няколко капки лимонов сок"]},"nl":{"name":"Gyroswrap met kip","description":"Kip met oregano in een tortilla met yoghurt, komkommer, tomaat en ui","instructions":["Snijd de kip in dunne reepjes, meng ze met de oregano, het paprikapoeder en zout en bak ze 5 tot 6 minuten in de olijfolie op hoog vuur","Snijd de komkommer, de tomaat en de ui in plakjes","Verwarm de tortilla, besmeer hem met de yoghurt en vul hem met de kip en de groenten","Knijp er citroensap over en rol op"],"seasonings":["1 tl gedroogde oregano","1/2 tl paprikapoeder","zout","kneepje citroensap"]}}'::jsonb, 198),
  ('l-salmon-couscous-bowl', 'Salmon Couscous Bowl', 'Flaked salmon over lemon couscous with cucumber, tomato and spinach', 'lunch', 'salmon', '🐟', 15, 'quick', 533, 34, 51, 22, 6, 5, 106, '[{"name":"salmon","amount":120,"unit":"g"},{"name":"couscous","amount":50,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"},{"name":"spinach","amount":30,"unit":"g"},{"name":"olive oil","amount":5,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["{70} ml boiling water","salt","black pepper"]'::jsonb, '["Pour the boiling water over the couscous with a pinch of salt, cover for 5 minutes and fluff with a fork","Fry the salmon in the olive oil over medium heat for 3 to 4 minutes per side and break into flakes","Dice the cucumber and tomato","Serve the couscous on the spinach with the vegetables and salmon, with the juice of the lemon squeezed over"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","fresh","quick","light","salmon","couscous","cucumber","tomato","spinach","olive oil","lemon","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Купа с кускус и сьомга","description":"Парченца сьомга върху кускус с лимон, краставица, домат и спанак","instructions":["Залейте кускуса с врящата вода и щипка сол, покрийте за 5 минути и го разрохкайте с вилица","Изпържете сьомгата в зехтина на среден огън по 3–4 минути от всяка страна и я разделете на парченца","Нарежете краставицата и домата на кубчета","Поднесете кускуса върху спанака със зеленчуците и сьомгата и изстискайте отгоре сока от лимона"],"seasonings":["{70} мл вряща вода","сол","черен пипер"]},"nl":{"name":"Couscousbowl met zalm","description":"Stukjes zalm op citroencouscous met komkommer, tomaat en spinazie","instructions":["Giet het kokende water over de couscous met een snufje zout, dek 5 minuten af en maak los met een vork","Bak de zalm 3 tot 4 minuten per kant in de olijfolie op middelhoog vuur en tre