  ('l-quinoa-greek-salad', 'Quinoa Greek Salad', 'Quinoa with chickpeas, feta, cucumber, tomato and peppers', 'lunch', 'chickpeas', '🥗', 20, 'quick', 531, 21, 65, 22, 11, 9, 616, '[{"name":"quinoa","amount":60,"unit":"g"},{"name":"chickpeas","amount":60,"unit":"g"},{"name":"feta","amount":40,"unit":"g"},{"name":"cucumber","amount":100,"unit":"g"},{"name":"tomato","amount":120,"unit":"g"},{"name":"peppers","amount":50,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","squeeze of lemon juice","salt"]'::jsonb, '["Rinse the quinoa and simmer it in salted water for 12 to 15 minutes, then drain and let it cool a little","Dice the cucumber, tomato and peppers","Toss the quinoa with the vegetables, drained chickpeas, olive oil, oregano and lemon juice","Crumble the feta over the top"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","fresh","quick","light","quinoa","chickpeas","feta","cucumber","tomato","peppers","olive oil","stovetop","lunch"]'::jsonb, '["vegetarian","gluten-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Гръцка салата с киноа","description":"Киноа с нахут, фета, краставица, домат и чушки","instructions":["Измийте киноата и я варете в подсолена вода на тих огън 12–15 минути, след което я отцедете и я оставете леко да изстине","Нарежете краставицата, домата и чушките на кубчета","Разбъркайте киноата със зеленчуците, отцедения нахут, зехтина, ригана и лимоновия сок","Натрошете фетата отгоре"],"seasonings":["1 ч.л. сух риган","няколко капки лимонов сок","сол"]},"nl":{"name":"Griekse quinoasalade","description":"Quinoa met kikkererwten, feta, komkommer, tomaat en paprika","instructions":["Spoel de quinoa af en laat hem 12 tot 15 minuten zachtjes koken in water met zout; giet af en laat iets afkoelen","Snijd de komkommer, de tomaat en de paprika in blokjes","Meng de quinoa met de groenten, de uitgelekte kikkererwten, de olijfolie, de oregano en het citroensap","Verkruimel de feta erover"],"seasonings":["1 tl gedroogde oregano","kneepje citroensap","zout"]}}'::jsonb, 200),
  ('l-spanish-omelette', 'Spanish Potato Omelette', 'Thick omelette of potato and onion cooked in olive oil', 'lunch', 'eggs', '🥔', 30, 'balanced', 520, 25, 42, 28, 5, 5, 249, '[{"name":"eggs","amount":3,"unit":"","label":"3 eggs"},{"name":"potatoes","amount":200,"unit":"g"},{"name":"onion","amount":60,"unit":"g"},{"name":"olive oil","amount":12,"unit":"g"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Cut the potatoes into thin slices and slice the onion","Cook them gently in the olive oil in a small non-stick pan, covered, for 12 to 15 minutes until soft but not browned","Beat the eggs with salt and pepper, stir in the potatoes and onion, and pour everything back into the pan","Cook over low heat for 5 minutes, flip using a plate and cook 3 more minutes until set"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","light","eggs","potatoes","onion","olive oil","stovetop","lunch"]'::jsonb, '["vegetarian","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Испански омлет с картофи","description":"Дебел омлет от картофи и лук, приготвен в зехтин","instructions":["Нарежете картофите на тънки резени, а лука на филийки","Гответе ги в зехтина на слаб огън в малък незалепващ тиган под капак 12–15 минути, докато омекнат, без да се зачервят","Разбийте яйцата със сол и пипер, добавете картофите и лука и изсипете всичко обратно в тигана","Гответе на слаб огън 5 минути, обърнете с помощта на чиния и гответе още 3 минути, докато стегне"],"seasonings":["сол","черен пипер"]},"nl":{"name":"Spaanse aardappelomelet","description":"Dikke omelet van aardappel en ui, gebakken in olijfolie","instructions":["Snijd de aardappelen in dunne plakjes en de ui in ringen","Bak ze 12 tot 15 minuten zachtjes in de olijfolie in een kleine koekenpan met antiaanbaklaag, met het deksel op de pan, tot ze zacht maar niet bruin zijn","Klop de eieren los met zout en peper, roer de aardappelen en de ui erdoor en giet alles terug in de pan","Bak 5 minuten op laag vuur, keer de omelet met behulp van een bord en bak nog 3 minuten tot hij gestold is"],"seasonings":["zout","zwarte peper"]}}'::jsonb, 201),
  ('l-garlic-shrimp-couscous', 'Garlic Shrimp with Zucchini Couscous', 'Chili-garlic shrimp over couscous with zucchini and lemon', 'lunch', 'shrimp', '🍤', 15, 'quick', 489, 39, 60, 12, 6, 5, 186, '[{"name":"shrimp","amount":140,"unit":"g"},{"name":"couscous","amount":60,"unit":"g"},{"name":"zucchini","amount":120,"unit":"g"},{"name":"garlic","amount":12,"unit":"g","label":"3 cloves"},{"name":"olive oil","amount":10,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["1/2 tsp chili flakes","{80} ml boiling water","salt"]'::jsonb, '["Pour the boiling water over the couscous with a pinch of salt, cover for 5 minutes and fluff with a fork","Dice the zucchini and fry it in the olive oil over high heat for 4 minutes","Add the shrimp, sliced garlic and chili flakes and cook for 2 to 3 minutes until the shrimp are pink","Serve over the couscous with the juice of the lemon"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","spicy","quick","light","shrimp","couscous","zucchini","garlic","olive oil","lemon","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Скариди с чесън и кускус с тиквичка","description":"Скариди с чили и чесън върху кускус с тиквичка и лимон","instructions":["Залейте кускуса с врящата вода и щипка сол, покрийте за 5 минути и го разрохкайте с вилица","Нарежете тиквичката на кубчета и я запържете в зехтина на силен огън за 4 минути","Добавете скаридите, нарязания чесън и люспите чили и гответе 2–3 минути, докато скаридите порозовеят","Поднесете върху кускуса със сока от лимона"],"seasonings":["1/2 ч.л. люспи чили","{80} мл вряща вода","сол"]},"nl":{"name":"Knoflookgarnalen met courgettecouscous","description":"Garnalen met chili en knoflook op couscous met courgette en citroen","instructions":["Giet het kokende water over de couscous met een snufje zout, dek 5 minuten af en maak los met een vork","Snijd de courgette in blokjes en bak ze 4 minuten in de olijfolie op hoog vuur","Voeg de garnalen, de plakjes knoflook en de chilivlokken toe en bak 2 tot 3 minuten tot de garnalen roze zijn","Serveer op de couscous met het sap van de citroen"],"seasonings":["1/2 tl chilivlokken","{80} ml kokend water","zout"]}}'::jsonb, 202),
  ('l-beef-kofta-wrap', 'Beef Kofta Wrap', 'Spiced beef kofta in a tortilla with yogurt, cucumber, tomato and lettuce', 'lunch', 'beef mince', '🌯', 20, 'quick', 497, 30, 37, 25, 4, 8, 550, '[{"name":"beef mince","amount":120,"unit":"g"},{"name":"tortilla","amount":1,"unit":"","label":"1 tortilla"},{"name":"yogurt","amount":50,"unit":"g"},{"name":"cucumber","amount":60,"unit":"g"},{"name":"tomato","amount":60,"unit":"g"},{"name":"lettuce","amount":30,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1/2 tsp paprika","1/2 tsp chili flakes","salt"]'::jsonb, '["Mix the beef mince with the cumin, paprika, chili flakes and salt and shape it into {3} short sausages","Fry them in a dry non-stick pan over medium-high heat for 8 minutes, turning, until browned and cooked through","Slice the cucumber and tomato and shred the lettuce","Warm the tortilla, spread with the yogurt, add the kofta and vegetables and roll up"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","spicy","quick","light","beef mince","tortilla","yogurt","cucumber","tomato","lettuce","stovetop","lunch"]'::jsonb, '["nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Врап с телешки кюфтенца кофта","description":"Телешка кофта с подправки в тортила с кисело мляко, краставица, домат и маруля","instructions":["Смесете телешката кайма с кимиона, червения пипер, люспите чили и сол и оформете {3} къси продълговати кюфтенца","Запържете ги в сух незалепващ тиган на умерено силен огън за 8 минути, като ги обръщате, докато се зачервят и се сготвят","Нарежете краставицата и домата на резени, а марулята на ивици","Затоплете тортилата, намажете я с киселото мляко, добавете кофтата и зеленчуците и навийте"],"seasonings":["1 ч.л. смлян кимион","1/2 ч.л. червен пипер","1/2 ч.л. люспи чили","сол"]},"nl":{"name":"Wrap met runderkofta","description":"Gekruide runderkofta in een tortilla met yoghurt, komkommer, tomaat en sla","instructions":["Meng het rundergehakt met de komijn, het paprikapoeder, de chilivlokken en zout en vorm er {3} korte worstjes van","Bak ze 8 minuten in een droge koekenpan met antiaanbaklaag op middelhoog tot hoog vuur bruin en gaar; keer regelmatig","Snijd de komkommer en de tomaat in plakjes en de sla in reepjes","Verwarm de tortilla, besmeer hem met de yoghurt, leg de kofta en de groenten erop en rol op"],"seasonings":["1 tl gemalen komijn","1/2 tl paprikapoeder","1/2 tl chilivlokken","zout"]}}'::jsonb, 203),
  ('l-mediterranean-tofu-bowl', 'Mediterranean Tofu Couscous Bowl', 'Oregano tofu with zucchini, peppers and tomato over couscous', 'lunch', 'tofu', '🥙', 20, 'quick', 531, 34, 58, 21, 10, 8, 40, '[{"name":"tofu","amount":140,"unit":"g"},{"name":"couscous","amount":55,"unit":"g"},{"name":"zucchini","amount":100,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"}]'::jsonb, '["1 tsp dried oregano","{75} ml boiling water","squeeze of lemon juice","salt"]'::jsonb, '["Pour the boiling water over the couscous with a pinch of salt, cover for 5 minutes and fluff with a fork","Cut the tofu into cubes and fry in the olive oil over medium-high heat for 5 minutes until golden","Add the diced zucchini and peppers with the oregano and cook for 5 minutes","Serve over the couscous with the diced tomato and a squeeze of lemon"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","quick","light","tofu","couscous","zucchini","peppers","tomato","olive oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Средиземноморска купа с тофу и кускус","description":"Тофу с риган, тиквичка, чушки и домат върху кускус","instructions":["Залейте кускуса с врящата вода и щипка сол, покрийте за 5 минути и го разрохкайте с вилица","Нарежете тофуто на кубчета и го запържете в зехтина на умерено силен огън за 5 минути до златисто","Добавете нарязаните на кубчета тиквичка и чушки с ригана и гответе 5 минути","Поднесете върху кускуса с нарязания на кубчета домат и няколко капки лимон"],"seasonings":["1 ч.л. сух риган","{75} мл вряща вода","няколко капки лимонов сок","сол"]},"nl":{"name":"Mediterrane couscousbowl met tofu","description":"Tofu met oregano, courgette, paprika en tomaat op couscous","instructions":["Giet het kokende water over de couscous met een snufje zout, dek 5 minuten af en maak los met een vork","Snijd de tofu in blokjes en bak ze 5 