  ('l-chicken-shawarma-rice-bowl', 'Chicken Shawarma Rice Bowl', 'Spiced chicken over rice with garlic yogurt, cucumber and tomato', 'lunch', 'chicken', '🍗', 25, 'balanced', 663, 46, 76, 18, 2, 6, 99, '[{"name":"chicken","amount":150,"unit":"g"},{"name":"rice","amount":85,"unit":"g"},{"name":"greek yogurt","amount":60,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","1/2 tsp chili flakes","1/2 tsp ground coriander","salt"]'::jsonb, '["Boil the rice in salted water for 10 to 12 minutes and drain","Slice the chicken thinly and coat it with the cumin, paprika, chili flakes, coriander and salt","Fry in the olive oil over high heat for 6 minutes until browned at the edges","Serve over the rice with the diced cucumber and tomato and a spoon of yogurt"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","spicy","hearty","chicken","rice","greek yogurt","cucumber","tomato","olive oil","stovetop","lunch"]'::jsonb, '["gluten-free","nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Купа ориз с пилешка шаурма","description":"Пилешко с подправки върху ориз с чесново кисело мляко, краставица и домат","instructions":["Сварете ориза в подсолена вода за 10–12 минути и го отцедете","Нарежете пилешкото на тънки ивици и го овкусете с кимиона, червения пипер, люспите чили, кориандъра и сол","Запържете в зехтина на силен огън за 6 минути, докато се зачерви по краищата","Поднесете върху ориза с нарязаните на кубчета краставица и домат и лъжица кисело мляко"],"seasonings":["1 ч.л. смлян кимион","1 ч.л. червен пипер","1/2 ч.л. люспи чили","1/2 ч.л. смлян кориандър","сол"]},"nl":{"name":"Rijstkom met kipshoarma","description":"Gekruide kip op rijst met knoflookyoghurt, komkommer en tomaat","instructions":["Kook de rijst 10 tot 12 minuten in water met zout en giet af","Snijd de kip in dunne reepjes en wentel ze door de komijn, het paprikapoeder, de chilivlokken, de koriander en zout","Bak 6 minuten in de olijfolie op hoog vuur tot de randjes bruin zijn","Serveer op de rijst met de blokjes komkommer en tomaat en een lepel yoghurt"],"seasonings":["1 tl gemalen komijn","1 tl paprikapoeder","1/2 tl chilivlokken","1/2 tl gemalen koriander","zout"]}}'::jsonb, 205),
  ('l-lentil-feta-salad', 'Lentil and Feta Salad', 'Warm lentils with feta, tomato, cucumber and spinach', 'lunch', 'lentils', '🥗', 30, 'balanced', 462, 26, 54, 18, 10, 6, 498, '[{"name":"lentils","amount":70,"unit":"g"},{"name":"feta","amount":40,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"cucumber","amount":80,"unit":"g"},{"name":"spinach","amount":40,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"}]'::jsonb, '["splash of red wine vinegar","salt","black pepper"]'::jsonb, '["Simmer the rinsed lentils in unsalted water for 20 to 25 minutes until tender but still holding their shape, then drain","Dice the tomato and cucumber","Toss the warm lentils with the olive oil, vinegar, salt and pepper, then fold in the spinach, tomato and cucumber","Crumble the feta over the top"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","fresh","light","lentils","feta","tomato","cucumber","spinach","olive oil","stovetop","lunch"]'::jsonb, '["vegetarian","gluten-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Салата с леща и фета","description":"Топла леща с фета, домат, краставица и спанак","instructions":["Варете измитата леща в неподсолена вода на тих огън 20–25 минути, докато омекне, но запази формата си, и я отцедете","Нарежете домата и краставицата на кубчета","Разбъркайте топлата леща със зехтина, оцета, сол и пипер, след което добавете спанака, домата и краставицата","Натрошете фетата отгоре"],"seasonings":["малко червен винен оцет","сол","черен пипер"]},"nl":{"name":"Salade met linzen en feta","description":"Warme linzen met feta, tomaat, komkommer en spinazie","instructions":["Laat de afgespoelde linzen 20 tot 25 minuten zachtjes koken in water zonder zout tot ze gaar zijn maar nog heel; giet af","Snijd de tomaat en de komkommer in blokjes","Meng de warme linzen met de olijfolie, de azijn, zout en peper en schep dan de spinazie, de tomaat en de komkommer erdoor","Verkruimel de feta erover"],"seasonings":["scheutje rodewijnazijn","zout","zwarte peper"]}}'::jsonb, 206),
  ('l-chicken-salad-wrap', 'Chicken Salad Wrap', 'Tortilla with chicken, lettuce, tomato, cucumber and a yogurt dressing', 'lunch', 'chicken', '🌯', 15, 'quick', 379, 35, 37, 10, 4, 7, 522, '[{"name":"chicken","amount":120,"unit":"g"},{"name":"tortilla","amount":1,"unit":"","label":"1 tortilla"},{"name":"lettuce","amount":50,"unit":"g"},{"name":"tomato","amount":60,"unit":"g"},{"name":"cucumber","amount":50,"unit":"g"},{"name":"yogurt","amount":40,"unit":"g"}]'::jsonb, '["1 tsp mustard","salt","black pepper"]'::jsonb, '["Season the chicken and fry it in a non-stick pan over medium heat for 5 to 6 minutes per side, then slice","Stir the mustard and a pinch of salt into the yogurt","Shred the lettuce and slice the tomato and cucumber","Spread the yogurt over the tortilla, add the chicken and vegetables and roll up"]'::jsonb, '["stovetop"]'::jsonb, '["fresh","quick","light","chicken","tortilla","lettuce","tomato","cucumber","yogurt","stovetop","lunch"]'::jsonb, '["nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Врап с пилешка салата","description":"Тортила с пилешко, маруля, домат, краставица и дресинг от кисело мляко","instructions":["Овкусете пилешкото и го изпържете в незалепващ тиган на среден огън по 5–6 минути от всяка страна, след което го нарежете","Разбъркайте горчицата и щипка сол в киселото мляко","Нарежете марулята на ивици, а домата и краставицата на резени","Намажете киселото мляко върху тортилата, добавете пилешкото и зеленчуците и навийте"],"seasonings":["1 ч.л. горчица","сол","черен пипер"]},"nl":{"name":"Wrap met kipsalade","description":"Tortilla met kip, sla, tomaat, komkommer en een yoghurtdressing","instructions":["Kruid de kip en bak hem in een koekenpan met antiaanbaklaag op middelhoog vuur 5 tot 6 minuten per kant; snijd hem dan in plakken","Roer de mosterd en een snufje zout door de yoghurt","Snijd de sla in reepjes en de tomaat en de komkommer in plakjes","Smeer de yoghurt over de tortilla, leg de kip en de groenten erop en rol op"],"seasonings":["1 tl mosterd","zout","zwarte peper"]}}'::jsonb, 207),
  ('l-egg-salad-sandwich', 'Egg Salad Sandwich', 'Chopped egg in a mustard yogurt dressing with lettuce and cucumber', 'lunch', 'eggs', '🥪', 15, 'quick', 365, 24, 35, 14, 5, 6, 492, '[{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"yogurt","amount":30,"unit":"g"},{"name":"lettuce","amount":30,"unit":"g"},{"name":"cucumber","amount":50,"unit":"g"}]'::jsonb, '["1 tsp mustard","salt","black pepper"]'::jsonb, '["Boil the eggs for 9 minutes, cool them under cold water and peel","Chop the eggs and mix with the yogurt, mustard, salt and pepper","Pile onto one slice of bread with the lettuce and sliced cucumber and top with the second slice"]'::jsonb, '["stovetop"]'::jsonb, '["quick","light","eggs","bread","yogurt","lettuce","cucumber","stovetop","lunch"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Сандвич с яйчена салата","description":"Нарязани яйца в дресинг от горчица и кисело мляко с маруля и краставица","instructions":["Сварете яйцата за 9 минути, охладете ги под студена вода и ги обелете","Нарежете яйцата и ги смесете с киселото мляко, горчицата, сол и пипер","Сложете сместа върху едната филийка с марулята и нарязаната краставица и покрийте с втората филийка"],"seasonings":["1 ч.л. горчица","сол","черен пипер"]},"nl":{"name":"Sandwich met eiersalade","description":"Gehakt ei in een dressing van mosterd en yoghurt met sla en komkommer","instructions":["Kook de eieren 9 minuten, laat ze schrikken onder koud water en pel ze","Hak de eieren en meng ze met de yoghurt, de mosterd, zout en peper","Schep op één sneetje brood met de sla en de plakjes komkommer en leg het tweede sneetje erop"],"seasonings":["1 tl mosterd","zout","zwarte peper"]}}'::jsonb, 208),
  ('l-tuna-melt-toastie', 'Tuna Melt Toastie', 'Pan-toasted sandwich with tuna, corn and melted cheese', 'lunch', 'tuna', '🥪', 10, 'quick', 423, 35, 36, 16, 5, 5, 901, '[{"name":"tuna","amount":90,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"cheese","amount":30,"unit":"g"},{"name":"corn","amount":40,"unit":"g"},{"name":"butter","amount":5,"unit":"g"}]'::jsonb, '["black pepper"]'::jsonb, '["Mix the drained tuna with the corn and pepper","Butter one side of each slice of bread and put one slice butter side down in a pan","Top with the tuna and grated cheese and the second slice, butter side up","Toast over medium heat for 2 to 3 minutes per side until golden and the cheese has melted"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","light","tuna","bread","cheese","corn","butter","stovetop","lunch"]'::jsonb, '["nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Тост с риба тон и разтопен кашкавал","description":"Запечен в тиган сандвич с риба тон, царевица и разтопен кашкавал","instructions":["Смесете отцедената риба тон с царевицата и пипер","Намажете едната страна на всяка филийка с масло и сложете едната филийка в тиган с маслото надолу","Сложете отгоре рибата тон и настъргания кашкавал и втората филийка с маслото нагоре","Запечете на среден огън по 2–3 минути от всяка страна, докато стане златист и кашкавалът се разтопи"],"seasonings":["черен пипер"]},"nl":{"name":"Tosti tuna melt","description":"In de pan gebakken tosti met tonijn, mais en gesmolten kaas","instructions":["Meng de uitgelekte tonijn met de mais en peper","Besmeer één kant van elk sneetje brood met boter en leg één sneetje met de boterkant naar beneden in een pan","Leg de tonijn en de geraspte kaas erop en dan het tweede sneetje, met de boterkant naar boven","Bak op middelhoog vuur 2 tot 3 minuten per kant, tot de tosti goudbruin is en de kaas gesmolten is"],"seasonings":["zwarte peper"]}}'::jsonb, 209),
  ('l-stuffed-sweet-potato-chickpeas', 'Stuffed Sweet Potato with Chickpeas', 'Baked sweet potato filled with spiced chickpeas and spinach', 'lunch', 'chickpeas', '🍠', 15, 'quick', 507, 15, 89, 12, 18, 18, 500, '[{"name":"sweet potato","amount":300,"unit":"g"},{"name":"chickpeas","amount":120,"unit":"g"},{"name":"spinach","amount":50,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"}]'::jsonb, '["1/2 tsp smoked paprika","1/2 tsp ground cumin","salt","squeeze of lemon juice"]'::jsonb, '["Prick the sweet potato all over and microwave on high for 8 to 10 minutes, turning once, until soft","Warm the drained chickpeas in the olive oil with the paprika, cumin and salt for 3 minutes","Stir in the spinach until it wilts","Split the sweet potato, fill it with the chickpeas and finish with lemon juice"]'::jsonb, '["stovetop","microwave"]'::jsonb, '["comfort","quick","light","sweet potato","chickpeas","spinach","olive oil","stovetop","microwave","lunch"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Пълнен сладък картоф с нахут","description":"Печен сладък картоф, пълнен с нахут с подправки и спанак","instructions":["Надупчете сладкия картоф от всички страни и го пригответе в микровълновата на висока мощност 8–10 минути, като го обърнете веднъж, докато омекне","Затоплете отцедения нахут в зехтина с червения пипер, кимиона и сол за 3 минути","Добавете спанака и бъркайте, докато омекне","Разрежете сладкия картоф, напълнете го с нахута и овкусете с лимонов сок"],"seasonings":["1/2 ч.л. пушен червен пипер","1/2 ч.л. смлян кимион","сол","няколко капки лимонов сок"]},"nl":{"name":"Gevulde zoete aardappel met kikkererwten","description":"Gepofte zoete aardappel gevuld met gekruide kikkererwten en spinazie","instructions":["Prik de zoete aardappel rondom in en gaar hem 8 tot 10 minuten in de magnetron op de hoogste stand; keer één keer, tot hij zacht is","Verwarm de uitgelekte kikkererwten 3 minuten in de olijfolie met het paprikapoeder, de komijn en zout","Roer de spinazie erdoor tot hij slinkt","Snijd de zoete aardappel open, vul hem met de kikkererwten en maak af met citroensap"],"seasonings":["1/2 tl gerookt paprikapoeder","1/2 tl gemalen komijn","zout","kneepje citroensap"]}}'::jsonb, 210),
  ('l-chicken-vegetable-soup', 'Chicken and Vegetable Soup', 'Clear soup with chicken, potato, carrot and peas', 'lunch', 'chicken', '🍲', 30, 'balanced', 407, 36, 45, 9, 8, 10, 179, '[{"name":"chicken","amount":130,"unit":"g"},{"name":"potatoes","amount":150,"unit":"g"},{"name":"carrots","amount":80,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"peas","amount":50,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 stock cube","{500} ml water","black pepper","handful of fresh parsley"]'::jsonb, '["Dice the onion and soften it in the oil in a pot for 3 minutes","Add the diced potatoes and carrots, the water, stock cube and the whole piece of chicken and simmer for 18 minutes","Lift out the chicken, shred it with two forks and return it to the pot with the peas","Cook 2 more minutes and season with pepper and parsley"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","light","chicken","potatoes","carrots","onion","peas","oil","stovetop","lunch"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Пилешка супа със зеленчуци","description":"Бистра супа с пилешко, картофи, моркови и грах","instructions":["Нарежете лука на кубчета и го задушете в олиото в тенджера за 3 минути","Добавете нарязаните на кубчета картофи и моркови, водата, кубчето бульон и цялото парче пилешко и варете на тих огън 18 минути","Извадете пилешкото, накъсайте го с две вилици и го върнете в тенджерата заедно с граха","Варете още 2 минути и овкусете с пипер и магданоз"],"seasonings":["1 кубче бульон","{500} мл вода","черен пипер","шепа пресен магданоз"]},"nl":{"name":"Kippensoep met groenten","description":"Heldere soep met kip, aardappel, wortel en doperwten","instructions":["Snijd de ui in blokjes en bak hem 3 minuten zacht in de olie in een pan","Voeg de blokjes aardappel en wortel, het water, het bouillonblokje en het hele stuk kip toe en laat 18 minuten zachtjes koken","Haal de kip eruit, trek hem met twee vorken uit elkaar en doe hem met de doperwten terug in de pan","Kook nog 2 minuten en breng op smaak met peper en peterselie"],"seasonings":["1 bouillonblokje","{500} ml water","zwarte peper","handje verse peterselie"]}}'::jsonb, 211),
  ('l-ham-cheese-spinach-omelette', 'Ham, Cheese and Spinach Omelette', 'Three-egg omelette with ham, cheese and spinach, with toast', 'lunch', 'eggs', '🧀', 10, 'quick', 542, 40, 20, 33, 4, 3, 1029, '[{"name":"eggs","amount":3,"unit":"","label":"3 eggs"},{"name":"ham","amount":40,"unit":"g"},{"name":"cheese","amount":30,"unit":"g"},{"name":"spinach","amount":40,"unit":"g"},{"name":"butter","amount":5,"unit":"g"},{"name":"bread","amount":35,"unit":"g","label":"1 slice"}]'::jsonb, '["black pepper"]'::jsonb, '["Beat the eggs with pepper, cut the ham into strips and grate the cheese","Melt the butter in a non-stick pan, wilt the spinach for 30 seconds and pour in the eggs","When almost set, scatter the ham and cheese over one half and fold over","Cook 1 more minute and serve with the toasted bread"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","light","eggs","ham","cheese","spinach","butter","bread","stovetop","lunch"]'::jsonb, '["nut-allergy"]'::jsonb, '{"bg":{"name":"Омлет с шунка, кашкавал и спанак","description":"Омлет от три яйца с шунка, кашкавал и спанак, с препечен хляб","instructions":["Разбийте яйцата с пипер, нарежете шунката на ивици и настържете кашкавала","Разтопете маслото в незалепващ тиган, задушете спанака за 30 секунди и изсипете яйцата","Когато почти стегнат, поръсете шунката и кашкавала върху едната половина и сгънете","Гответе още 1 минута и поднесете с препечения хляб"],"seasonings":["черен пипер"]},"nl":{"name":"Omelet met ham, kaas en spinazie","description":"Omelet van drie eieren met ham, kaas en spinazie, met toast","instructions":["Klop de eieren los met peper, snijd de ham in reepjes en rasp de kaas","Smelt de boter in een koekenpan met antiaanbaklaag, laat de spinazie 30 seconden slinken en giet de eieren erin","Strooi de ham en de kaas over één helft als het ei bijna gestold is en klap dicht","Bak nog 1 minuut en serveer met het geroosterde brood"],"seasonings":["zwarte peper"]}}'::jsonb, 212),
  ('l-warm-salmon-potato-salad', 'Warm Salmon and Potato Salad', 'Flaked salmon with potatoes and green beans in a lemon yogurt dressing', 'lunch', 'salmon', '🥔', 25, 'balanced', 514, 32, 48, 23, 8, 8, 107, '[{"name":"salmon","amount":120,"unit":"g"},{"name":"potatoes","amount":200,"unit":"g"},{"name":"green beans","amount":80,"unit":"g"},{"name":"yogurt","amount":40,"unit":"g"},{"name":"olive oil","amount":5,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["1 tsp mustard","salt","black pepper"]'::jsonb, '["Boil the potatoes, cut into chunks, in salted water for 15 minutes, adding the green beans for the last 5, then drain","Fry the salmon in the olive oil over medium heat for 3 to 4 minutes per side and break into flakes","Mix the yogurt with the mustard, the juice of the lemon, salt and pepper","Toss the warm potatoes and beans in the dressing and fold in the salmon"]'::jsonb, '["stovetop"]'::jsonb, '["fresh","light","salmon","potatoes","green beans","yogurt","olive oil","lemon","stovetop","lunch"]'::jsonb, '["gluten-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Топла салата със сьомга и картофи","description":"Парченца сьомга с картофи и зелен фасул в дресинг от лимон и кисело мляко","instructions":["Сварете картофите, нарязани на парчета, в подсолена вода за 15 минути, като през последните 5 добавите зеления фасул, и отцедете","Изпържете сьомгата в зехтина на среден огън по 3–4 минути от всяка страна и я разделете на парченца","Смесете киселото мляко с горчицата, сока от лимона, сол и пипер","Разбъркайте топлите картофи и фасула с дресинга и добавете внимателно сьомгата"],"seasonings":["1 ч.л. горчица","сол","черен пипер"]},"nl":{"name":"Warme salade met zalm en aardappel","description":"Stukjes zalm met aardappelen en sperziebonen in een dressing van citroen en yoghurt","instructions":["Kook de aardappelen, in stukken gesneden, 15 minuten in water met zout, kook de sperziebonen de laatste 5 minuten mee en giet af","Bak de zalm 3 tot 4 minuten per kant in de olijfolie op middelhoog vuur en trek hem in stukjes","Meng de yoghurt met de mosterd, het sap van de citroen, zout en peper","Schep de warme aardappelen en bonen door de dressing en schep de zalm erdoor"],"seasonings":["1 tl mosterd","zout","zwarte peper"]}}'::jsonb, 213),
  ('l-turkey-bacon-avocado-sandwich', 'Turkey, Bacon and Avocado Sandwich', 'Toasted sandwich with turkey, crisp bacon, avocado and tomato', 'lunch', 'turkey', '🥪', 15, 'quick', 627, 39, 45, 35, 15, 6, 595, '[{"name":"turkey","amount":100,"unit":"g"},{"name":"bacon","amount":25,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"tomato","amount":60,"unit":"g"},{"name":"lettuce","amount":20,"unit":"g"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Fry the bacon in a dry pan over medium heat for 4 minutes until crisp and set it aside","Slice the turkey thinly, season and fry it in the bacon fat for 4 minutes until cooked through","Toast the bread and spread it with the mashed avocado","Layer on the turkey, bacon, sliced tomato and lettuce"]'::jsonb, '["stovetop"]'::jsonb, '["quick","turkey","bacon","bread","avocado","tomato","lettuce","stovetop","lunch"]'::jsonb, '["dairy-free","nut-allergy"]'::jsonb, '{"bg":{"name":"Сандвич с пуешко, бекон и авокадо","description":"Препечен сандвич с пуешко, хрупкав бекон, авокадо и домат","instructions":["Изпържете бекона в сух тиган на среден огън за 4 минути, докато стане хрупкав, и го оставете настрани","Нарежете пуешкото на тънки резени, овкусете го и го изпържете в мазнината от бекона за 4 минути, докато се сготви","Препечете хляба и го намажете с намачканото авокадо","Наредете пуешкото, бекона, нарязания домат и марулята"],"seasonings":["сол","черен пипер"]},"nl":{"name":"Sandwich met kalkoen, spek en avocado","description":"Geroosterde sandwich met kalkoen, knapperig spek, avocado en tomaat","instructions":["Bak het spek 4 minuten in een droge pan op middelhoog vuur knapperig en leg het apart","Snijd de kalkoen in dunne plakjes, kruid ze en bak ze 4 minuten in het spekvet tot ze gaar zijn","Rooster het brood en besmeer het met de geprakte avocado","Beleg met de kalkoen, het spek, de plakjes tomaat en de sla"],"seasonings":["zout","zwarte peper"]}}'::jsonb, 214),
  ('l-chicken-quinoa-bowl', 'Chicken Quinoa Bowl', 'Quinoa with chicken, broccoli and carrot in a lemon olive oil dressing', 'lunch', 'chicken', '🥗', 20, 'quick', 519, 42, 56, 16, 10, 6, 130, '[{"name":"chicken","amount":130,"unit":"g"},{"name":"quinoa","amount":60,"unit":"g"},{"name":"broccoli","amount":100,"unit":"g"},{"name":"carrots","amount":50,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"},{"name":"lemon","amount":1,"unit":"","label":"1 lemon"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Rinse the quinoa and simmer it in salted water for 12 to 15 minutes, adding the broccoli florets for the last 3, then drain","Season the chicken and fry it in half the olive oil for 5 to 6 minutes per side, then slice","Grate the carrots","Serve the quinoa and broccoli topped with the chicken and carrots, dressed with the remaining olive oil and the juice of the lemon"]'::jsonb, '["stovetop"]'::jsonb, '["quick","light","chicken","quinoa","broccoli","carrots","olive oil","lemon","stovetop","lunch"]'::jsonb, '["gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Купа с киноа и пилешко","description":"Киноа с пилешко, броколи и морков в дресинг от лимон и зехтин","instructions":["Измийте киноата и я варете в подсолена вода на тих огън 12–15 минути, като през последните 3 добавите розичките броколи, и отцедете","Овкусете пилешкото и го изпържете в половината зехтин по 5–6 минути от всяка страна, след което го нарежете","Настържете морковите","Поднесете киноата и броколите с пилешкото и морковите отгоре, овкусени с останалия зехтин и сока от лимона"],"seasonings":["сол","черен пипер"]},"nl":{"name":"Quinoabowl met kip","description":"Quinoa met kip, broccoli en wortel in een dressing van citroen en olijfolie","instructions":["Spoel de quinoa af en laat hem 12 tot 15 minuten zachtjes koken in water met zout; kook de broccoliroosjes de laatste 3 minuten mee en giet af","Kruid de kip en bak hem in de helft van de olijfolie 5 tot 6 minuten per 