  ('l-chicken-pesto-panini', 'Chicken Pesto Panini', 'Pressed sandwich with chicken, mozzarella, tomato and pesto', 'lunch', 'chicken', '🥪', 20, 'quick', 745, 62, 51, 32, 8, 7, 1090, '[{"name":"chicken","amount":150,"unit":"g"},{"name":"bread","amount":105,"unit":"g","label":"3 slices"},{"name":"mozzarella","amount":60,"unit":"g"},{"name":"pesto","amount":25,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Season the chicken and fry it in a non-stick pan over medium heat for 5 to 6 minutes per side, then slice","Spread the pesto on the bread and layer on the chicken, sliced mozzarella and sliced tomato to make a double-decker sandwich","Toast it in the dry pan over medium heat, pressing down with a spatula, for 2 to 3 minutes per side until the cheese melts"]'::jsonb, '["stovetop"]'::jsonb, '["italian","quick","hearty","chicken","bread","mozzarella","pesto","tomato","stovetop","lunch"]'::jsonb, '["halal"]'::jsonb, '{"bg":{"name":"Панини с пилешко и песто","description":"Притиснат сандвич с пилешко, моцарела, домат и песто","instructions":["Овкусете пилешкото и го изпържете в незалепващ тиган на среден огън по 5–6 минути от всяка страна, след което го нарежете","Намажете пестото върху хляба и наредете пилешкото, нарязаната моцарела и нарязания домат, така че да се получи сандвич на два етажа","Запечете го в сухия тиган на среден огън по 2–3 минути от всяка страна, като го притискате с шпатула, докато моцарелата се разтопи"],"seasonings":["сол","черен пипер"]},"nl":{"name":"Panini met kip en pesto","description":"Geperste sandwich met kip, mozzarella, tomaat en pesto","instructions":["Kruid de kip en bak hem in een koekenpan met antiaanbaklaag op middelhoog vuur 5 tot 6 minuten per kant; snijd hem dan in plakken","Smeer de pesto op het brood en beleg met de kip, de plakjes mozzarella en de plakjes tomaat tot een sandwich van twee lagen","Bak hem in de droge pan op middelhoog vuur 2 tot 3 minuten per kant en druk hem aan met een spatel, tot de kaas smelt"],"seasonings":["zout","zwarte peper"]}}'::jsonb, 230),
  ('l-beef-bean-burrito', 'Beef and Bean Lunch Burritos', 'Two burritos with spiced beef mince, kidney beans and cheese', 'lunch', 'beef mince', '🌯', 20, 'quick', 825, 46, 75, 37, 8, 9, 1281, '[{"name":"beef mince","amount":140,"unit":"g"},{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"kidney beans","amount":60,"unit":"g"},{"name":"cheese","amount":20,"unit":"g"},{"name":"tomato","amount":60,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","salt"]'::jsonb, '["Brown the beef mince in a dry pan over high heat for 6 minutes","Add the cumin, paprika, salt, drained kidney beans and a splash of water and cook for 2 minutes","Warm the tortillas in a dry pan","Fill them with the beef and beans, grated cheese and diced tomato, fold in the sides and roll up"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","quick","hearty","beef mince","tortilla","kidney beans","cheese","tomato","stovetop","lunch"]'::jsonb, '["nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Бурито с телешка кайма и боб за обяд","description":"Две бурито с телешка кайма с подправки, червен боб и кашкавал","instructions":["Запържете телешката кайма в сух тиган на силен огън за 6 минути","Добавете кимиона, червения пипер, сол, отцедения червен боб и малко вода и гответе 2 минути","Затоплете тортилите в сух тиган","Напълнете ги с каймата и боба, настъргания кашкавал и нарязания на кубчета домат, подгънете краищата и навийте"],"seasonings":["1 ч.л. смлян кимион","1 ч.л. червен пипер","сол"]},"nl":{"name":"Lunchburrito''s met rundergehakt en bonen","description":"Twee burrito''s met gekruid rundergehakt, kidneybonen en kaas","instructions":["Bak het rundergehakt 6 minuten bruin in een droge pan op hoog vuur","Voeg de komijn, het paprikapoeder, zout, de uitgelekte kidneybonen en een scheutje water toe en bak 2 minuten","Verwarm de tortilla''s in een droge pan","Vul ze met het gehakt en de bonen, de geraspte kaas en de tomatenblokjes, vouw de zijkanten naar binnen en rol op"],"seasonin