  ('l-lentil-chickpea-power-bowl', 'Lentil and Chickpea Power Bowl', 'Warm lentils and chickpeas with avocado and tomato', 'lunch', 'lentils', '🥑', 30, 'balanced', 735, 32, 94, 30, 27, 10, 315, '[{"name":"lentils","amount":80,"unit":"g"},{"name":"chickpeas","amount":120,"unit":"g"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"tomato","amount":100,"unit":"g"},{"name":"olive oil","amount":5,"unit":"g"}]'::jsonb, '["splash of red wine vinegar","1/2 tsp ground cumin","salt","black pepper"]'::jsonb, '["Simmer the rinsed lentils in unsalted water for 20 to 25 minutes until tender, adding the drained chickpeas for the last 2 minutes, then drain","Toss with the olive oil, vinegar, cumin, salt and pepper","Dice the tomato and avocado and fold them through"]'::jsonb, '["stovetop"]'::jsonb, '["fresh","hearty","lentils","chickpeas","avocado","tomato","olive oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Енергийна купа с леща и нахут","description":"Топли леща и нахут с авокадо и домат","instructions":["Варете измитата леща в неподсолена вода на тих огън 20–25 минути, докато омекне, като през последните 2 минути добавите отцедения нахут, и отцедете","Разбъркайте със зехтина, оцета, кимиона, сол и пипер","Нарежете домата и авокадото на кубчета и ги добавете внимателно"],"seasonings":["малко червен винен оцет","1/2 ч.л. смлян кимион","сол","черен пипер"]},"nl":{"name":"Powerbowl met linzen en kikkererwten","description":"Warme linzen en kikkererwten met avocado en tomaat","instructions":["Laat de afgespoelde linzen 20 tot 25 minuten zachtjes koken in water zonder zout tot ze gaar zijn, kook de uitgelekte kikkererwten de laatste 2 minuten mee en giet af","Meng met de olijfolie, de azijn, de komijn, zout en peper","Snijd de tomaat en de avocado in blokjes en schep ze erdoor"],"seasonings":["scheutje rodewijnazijn","1/2 tl gemalen komijn","zout","zwarte peper"]}}'::jsonb, 238),
  ('l-turkey-cheese-quesadilla', 'Turkey and Cheese Quesadilla', 'Crisp tortillas with turkey, peppers and melted cheese', 'lunch', 'turkey', '🧀', 20, 'quick', 765, 56, 64, 32, 5, 8, 1399, '[{"name":"turkey","amount":140,"unit":"g"},{"name":"tortilla","amount":2,"unit":"","label":"2 tortillas"},{"name":"cheese","amount":50,"unit":"g"},{"name":"peppers","amount":60,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp paprika","1/2 tsp ground cumin","salt"]'::jsonb, '["Slice the turkey thinly, season with the paprika, cumin and salt and fry in the oil with the diced peppers for 6 minutes","Cover one tortilla with half the grated cheese, the turkey and peppers and the rest of the cheese, and top with the second tortilla","Cook in a clean dry pan over medium heat for 3 minutes per side until golden","Cut into wedges"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","quick","hearty","turkey","tortilla","cheese","peppers","oil","stovetop","lunch"]'::jsonb, '["nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Кесадия с пуешко и кашкавал","description":"Хрупкави тортили с пуешко, чушки и разтопен кашкавал","instructions":["Нарежете пуешкото на тънки ивици, овкусете го с червения пипер, кимиона и сол и го запържете в олиото с нарязаните на кубчета чушки за 6 минути","Покрийте едната тортила с половината настърган кашкавал, пуешкото с чушките и останалия кашкавал и сложете отгоре втората тортила","Печете в чист сух тиган на среден огън по 3 минути от всяка страна до златисто","Нарежете на триъгълници"],"seasonings":["1 ч.л. червен пипер","1/2 ч.л. смлян кимион","сол"]},"nl":{"name":"Quesadilla met kalkoen en kaas","description":"Knapperige tortilla''s met kalkoen, paprika en gesmolten kaas","instructions":["Snijd de kalkoen in dunne reepjes, kruid ze met het paprikapoeder, de komijn en zout en bak ze 6 minuten in de olie met de blokjes paprika","Beleg één tortilla met de helft van de geraspte kaas, de kalkoen met paprika en de rest van de kaas en leg de tweede tortilla erop","Bak in een schone droge pan op middelhoog vuur 3 minuten per kant goudbruin","Snijd in punten"],"seasonings":["1 tl paprikapoeder","1/2 tl gemalen komijn","zout"]}}'::jsonb, 239),
  ('l-bacon-egg-potato-hash', 'Bacon, Egg and Potato Hash', 'Crisp potatoes with bacon and onion, topped with three fried eggs', 'lunch', 'eggs', '🥓', 25, 'balanced', 724, 34, 57, 40, 7, 5, 629, '[{"name":"eggs","amount":3,"unit":"","label":"3 eggs"},{"name":"potatoes","amount":300,"unit":"g"},{"name":"bacon","amount":50,"unit":"g"},{"name":"onion","amount":40,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1/2 tsp paprika","black pepper"]'::jsonb, '["Cut the potatoes into 1 cm cubes and fry them in the oil over medium heat for 12 minutes until golden","Add the chopped bacon and diced onion with the paprika and cook for 5 minutes until the bacon is crisp","Make {n:eggs} gaps in the hash, crack in the eggs, cover and cook for 3 minutes until the whites are set","Season with pepper"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","hearty","eggs","potatoes","bacon","onion","oil","stovetop","lunch"]'::jsonb, '["gluten-free","dairy-free","nut-allergy"]'::jsonb, '{"bg":{"name":"Хаш с бекон, яйца и картофи","description":"Хрупкави картофи с бекон и лук, с три яйца на очи отгоре","instructions":["Нарежете картофите на кубчета от 1 см и ги пържете в олиото на среден огън 12 минути до златисто","Добавете нарязания бекон и нарязания на кубчета лук с червения пипер и гответе 5 минути, докато беконът стане хрупкав","Направете {n:eggs} гнезда в сместа, чукнете яйцата в тях, покрийте и гответе 3 минути, докато белтъкът стегне","Овкусете с пипер"],"seasonings":["1/2 ч.л. червен пипер","черен пипер"]},"nl":{"name":"Hash met spek, ei en aardappel","description":"Knapperige aardappelen met spek en ui, met drie gebakken eieren erop","instructions":["Snijd de aardappelen in blokjes van 1 cm en bak ze 12 minuten in de olie op middelhoog vuur goudbruin","Voeg het gesneden spek en de blokjes ui met het paprikapoeder toe en bak 5 minuten tot het spek knapperig is","Maak {n:eggs} kuiltjes in de hash, breek de eieren erin, dek af en bak 3 minuten tot het eiwit gestold is","Breng op smaak met peper"],"seasonings":["1/2 tl paprikapoeder","zwarte peper"]}}'::jsonb, 240),
  ('l-creamy-garlic-shrimp-pasta', 'Creamy Garlic Shrimp Pasta', 'Pasta with shrimp and spinach in a garlic parmesan cream sauce', 'lunch', 'shrimp', '🍤', 15, 'quick', 733, 54, 80, 22, 4, 6, 471, '[{"name":"shrimp","amount":160,"unit":"g"},{"name":"pasta","amount":95,"unit":"g"},{"name":"cream sauce","amount":80,"unit":"g"},{"name":"garlic","amount":12,"unit":"g","label":"3 cloves"},{"name":"parmesan","amount":15,"unit":"g"},{"name":"spinach","amount":50,"unit":"g"}]'::jsonb, '["black pepper","squeeze of lemon juice"]'::jsonb, '["Cook the pasta in salted boiling water according to the packet and drain, keeping a little of the water","Fry the shrimp in a non-stick pan over high heat for 2 minutes with the sliced garlic","Add the cream sauce, spinach and a splash of pasta water and simmer for 2 minutes","Toss in the pasta and grated parmesan and finish with pepper and lemon juice"]'::jsonb, '["stovetop"]'::jsonb, '["italian","comfort","quick","hearty","shrimp","pasta","cream sauce","garlic","parmesan","spinach","stovetop","lunch"]'::jsonb, '["nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Кремообразна паста със скариди и чесън","description":"Паста със скариди и спанак в сметанов сос с чесън и пармезан","instructions":["Сварете пастата в подсолена вряща вода според указанията на опаковката и я отцедете, като запазите малко от водата","Запържете скаридите в незалепващ тиган на силен огън за 2 минути с нарязания чесън","Добавете сметановия сос, спанака и малко от водата от пастата и варете на тих огън 2 минути","Добавете пастата и настъргания пармезан, разбъркайте и овкусете с пипер и лимонов сок"],"seasonings":["черен пипер","няколко капки лимонов сок"]},"nl":{"name":"Romige pasta met knoflookgarnalen","description":"Pasta met garnalen en spinazie in een roomsaus met knoflook en Parmezaanse kaas","instructions":["Kook de pasta in kokend water met zout volgens de verpakking en giet af; bewaar een beetje kookvocht","Bak de garnalen 2 minuten in een koekenpan met antiaanbaklaag op hoog vuur met de plakjes knoflook","Voeg de roomsaus, de spinazie en een scheutje kookvocht toe en laat 2 minuten zachtjes koken","Schep de pasta en de geraspte Parmezaanse kaas erdoor en maak af met peper en citroensap"],"seasonings":["zwarte peper","kneepje citroensap"]}}'::jsonb, 241),
  ('l-chicken-meatball-sub', 'Chicken Meatball Sub', 'Chicken meatballs in tomato sauce with melted mozzarella in bread', 'lunch', 'chicken mince', '🥖', 25, 'balanced', 681, 54, 55, 28, 8, 9, 845, '[{"name":"chicken mince","amount":160,"unit":"g"},{"name":"bread","amount":105,"unit":"g","label":"3 slices"},{"name":"tomato sauce","amount":100,"unit":"g"},{"name":"mozzarella","amount":50,"unit":"g"}]'::jsonb, '["1/2 tsp dried oregano","salt","black pepper"]'::jsonb, '["Season the chicken mince with the oregano, salt and pepper and roll it into {6} balls","Brown them in a non-stick pan for 6 minutes, turning","Add the tomato sauce, cover and simmer for 6 minutes until cooked through","Pile the meatballs and sauce onto the bread, top with the sliced mozzarella and let it melt for a minute before closing the sandwich"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","hearty","chicken mince","bread","tomato sauce","mozzarella","stovetop","lunch"]'::jsonb, '["nut-allergy","halal"]'::jsonb, '{"bg":{"name":"Сандвич с пилешки кюфтенца","description":"Пилешки кюфтенца в доматен сос с разтопена моцарела в хляб","instructions":["Овкусете пилешката кайма с ригана, сол и пипер и оформете {6} топчета","Запържете ги в незалепващ тиган за 6 минути, като ги обръщате","Добавете доматения сос, покрийте и варете на тих огън 6 минути, докато се сготвят","Сложете кюфтенцата със соса върху хляба, наредете отгоре нарязаната моцарела и я оставете да се разтопи за минута, преди да затворите сандвича"],"seasonings":["1/2 ч.л. сух риган","сол","черен пипер"]},"nl":{"name":"Broodje kipgehaktballetjes","description":"Balletjes van kipgehakt in tomatensaus met gesmolten mozzarella op brood","instructions":["Kruid het kipgehakt met de oregano, zout en peper en rol er {6} balletjes van","Bak ze 6 minuten rondom bruin in een koekenpan met antiaanbaklaag; keer regelmatig","Voeg de tomatensaus toe, dek af en laat 6 minuten zachtjes koken tot ze gaar zijn","Schep de balletjes met de saus op het brood, leg de plakjes mozzarella erop en laat ze een minuut smelten voordat je de sandwich dichtklapt"],"seasonings":["1/2 tl gedroogde oregano","zout","zwarte peper"]}}'::jsonb, 242),
  ('l-tofu-lentil-salad', 'Warm Tofu and Lentil Salad', 'Golden tofu over lentils with tomato, cucumber and a lemon dressing', 'lunch', 'tofu', '🥗', 25, 'balanced', 496, 40, 43, 22, 11, 5, 31, '[{"name":"tofu","amount":150,"unit":"g"},{"name":"lentils","amount":50,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"cucumber","amount":100,"unit":"g"},{"name":"olive oil","amount":8,"unit":"g"}]'::jsonb, '["1 tbsp lemon juice","pinch of dried oregano","pinch of salt","black pepper"]'::jsonb, '["Rinse the lentils and simmer them in {300} ml of salted water for 18 to 20 minutes until tender, then drain","Pat the tofu dry, cut it into cubes and fry it in half of the olive oil over medium-high heat for 6 to 8 minutes until golden","Dice the tomato and the cucumber and toss them with the lentils, the rest of the olive oil, the lemon juice, oregano, salt and black pepper","Top the salad with the warm tofu"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","fresh","light","tofu","lentils","tomato","cucumber","olive oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Топла салата с тофу и леща","description":"Златисто тофу върху леща с домат, краставица и лимонов дресинг","instructions":["Измийте лещата и я варете в {300} мл подсолена вода на тих огън 18–20 минути, докато омекне, и я отцедете","Подсушете тофуто, нарежете го на кубчета и го запържете в половината зехтин на умерено силен огън за 6–8 минути до златисто","Нарежете домата и краставицата на кубчета и ги разбъркайте с лещата, останалия зехтин, лимоновия сок, ригана, сол и черен пипер","Сложете топлото тофу върху салатата"],"seasonings":["1 с.л. лимонов сок","щипка сух риган","щипка сол","черен пипер"]},"nl":{"name":"Warme salade met tofu en linzen","description":"Goudbruine tofu op linzen met tomaat, komkommer en een citroendressing","instructions":["Spoel de linzen af en laat ze 18 tot 20 minuten zachtjes koken in {300} ml water met zout tot ze gaar zijn; giet af","Dep de tofu droog, snijd hem in blokjes en bak hem 6 tot 8 minuten in de helft van de olijfolie op middelhoog tot hoog vuur goudbruin","Snijd de tomaat en de komkommer in blokjes en meng ze met de linzen, de rest van de olijfolie, het citroensap, de oregano, zout en zwarte peper","Leg de warme tofu op de salade"],"seasonings":["1 el citroensap","snufje gedroogde oregano","snufje zout","zwarte peper"]}}'::jsonb, 243),
  ('l-chickpea-tofu-spinach-bowl', 'Chickpea and Tofu Spinach Bowl', 'Chickpeas and crumbled tofu fried with spinach, tomato and smoked paprika', 'lunch', 'chickpeas', '🥘', 15, 'quick', 548, 45, 46, 25, 17, 9, 462, '[{"name":"chickpeas","amount":150,"unit":"g"},{"name":"tofu","amount":180,"unit":"g"},{"name":"spinach","amount":80,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp smoked paprika","pinch of cumin","pinch of salt","black pepper"]'::jsonb, '["Drain and rinse the chickpeas, crumble the tofu and dice the tomato","Heat the oil in a pan over medium-high heat and fry the tofu and the chickpeas with the smoked paprika, cumin and salt for 6 minutes until they start to colour","Add the tomato and the spinach and cook for 2 minutes until the spinach has wilted","Season with black pepper and serve in a bowl"]'::jsonb, '["stovetop"]'::jsonb, '["quick","light","chickpeas","tofu","spinach","tomato","oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Купа с нахут, тофу и спанак","description":"Нахут и натрошено тофу, запържени със спанак, домат и пушен червен пипер","instructions":["Отцедете и изплакнете нахута, натрошете тофуто и нарежете домата на кубчета","Загрейте олиото в тиган на умерено силен огън и запържете тофуто и нахута с пушения червен пипер, кимиона и сол за 6 минути, докато започнат да се зачервяват","Добавете домата и спанака и гответе 2 минути, докато спанакът омекне","Овкусете с черен пипер и поднесете в купа"],"seasonings":["1 ч.л. пушен червен пипер","щипка кимион","щипка сол","черен пипер"]},"nl":{"name":"Bowl met kikkererwten, tofu en spinazie","description":"Kikkererwten en verkruimelde tofu gebakken met spinazie, tomaat en gerookt paprikapoeder","instructions":["Laat de kikkererwten uitlekken en spoel ze af, verkruimel de tofu en snijd de tomaat in blokjes","Verhit de olie in een pan op middelhoog tot hoog vuur en bak de tofu en de kikkererwten 6 minuten met het gerookte paprikapoeder, de komijn en zout, tot ze beginnen te kleuren","Voeg de tomaat en de spinazie toe en bak 2 minuten tot de spinazie geslonken is","Breng op smaak met zwarte peper en serveer in een kom"],"seasonings":["1 tl gerookt paprikapoeder","snufje komijn","snufje zout","zwarte peper"]}}'::jsonb, 244),
  ('l-teriyaki-tofu-pea-rice-bowl', 'Teriyaki Tofu Rice Bowl', 'Seared tofu glazed with teriyaki over rice with peas and carrot', 'lunch', 'tofu', '🍚', 20, 'quick', 644, 49, 64, 25, 12, 13, 1346, '[{"name":"tofu","amount":220,"unit":"g"},{"name":"rice","amount":40,"unit":"g"},{"name":"peas","amount":100,"unit":"g"},{"name":"carrots","amount":80,"unit":"g"},{"name":"teriyaki","amount":25,"unit":"ml"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '[]'::jsonb, '["Cook the rice in {100} ml of salted water, covered, for 12 minutes, then leave it to steam off the heat","Pat the tofu dry and cut it into cubes; slice the carrots thinly","Heat the oil in a pan over medium-high heat and fry the tofu for 6 minutes until golden, then add the carrots and the peas and cook for 3 minutes","Pour in the teriyaki, toss for 1 minute until glossy, and serve over the rice"]'::jsonb, '["stovetop"]'::jsonb, '["asian","quick","tofu","rice","peas","carrots","teriyaki","oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Купа ориз с тофу терияки","description":"Запечатано тофу, глазирано с терияки, върху ориз с грах и морков","instructions":["Сварете ориза в {100} мл подсолена вода под капак за 12 минути, след което го оставете да се задуши встрани от огъня","Подсушете тофуто и го нарежете на кубчета; нарежете морковите на тънки кръгчета","Загрейте олиото в тиган на умерено силен огън и запържете тофуто за 6 минути до златисто, след което добавете морковите и граха и гответе 3 минути","Изсипете соса терияки, разбъркайте 1 минута, докато всичко стане лъскаво, и поднесете върху ориза"],"seasonings":[]},"nl":{"name":"Rijstkom met teriyakitofu","description":"Aangebakken tofu geglaceerd met teriyaki op rijst met doperwten en wortel","instructions":["Kook de rijst 12 minuten met het deksel op de pan in {100} ml water met zout en laat hem dan van het vuur af nastomen","Dep de tofu droog en snijd hem in blokjes; snijd de wortels in dunne plakjes","Verhit de olie in een pan op middelhoog tot hoog vuur en bak de tofu 6 minuten goudbruin; voeg dan de wortels en de doperwten toe en bak 3 minuten","Giet de teriyaki erbij, schep 1 minuut om tot alles glanst en serveer op de rijst"],"seasonings":[]}}'::jsonb, 245),
  ('l-bean-tofu-burrito-bowl', 'Bean and Tofu Burrito Bowl', 'Kidney beans and spiced tofu with corn, peppers and fresh tomato, no rice', 'lunch', 'kidney beans', '🌶️', 15, 'quick', 565, 46, 54, 23, 16, 14, 502, '[{"name":"kidney beans","amount":150,"unit":"g"},{"name":"tofu","amount":180,"unit":"g"},{"name":"corn","amount":60,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"tomato","amount":80,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["1 tsp cumin","1 tsp smoked paprika","pinch of salt","squeeze of lime or lemon juice"]'::jsonb, '["Drain and rinse the beans and the corn; dice the peppers and the tomato and crumble the tofu into chunks","Heat the oil in a pan over medium-high heat and fry the tofu with the cumin, smoked paprika and salt for 5 minutes","Add the peppers, the beans and the corn and cook for 4 minutes until hot","Serve in a bowl with the tomato on top and a squeeze of lime or lemon juice"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","quick","kidney beans","tofu","corn","peppers","tomato","oil","stovetop","lunch"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, '{"bg":{"name":"Бурито купа с боб и тофу","description":"Червен боб и тофу с подправки, царевица, чушки и пресен домат, без ориз","instructions":["Отцедете и изплакнете боба и царевицата; нарежете чушките и домата на кубчета и натрошете тофуто на парчета","Загрейте олиото в тиган на умерено силен огън и запържете тофуто с кимиона, пушения червен пипер и сол за 5 минути","Добавете чушките, боба и царевицата и гответе 4 минути, докато се затоплят добре","Поднесете в купа с домата отгоре и няколко капки сок от лайм или лимон"],"seasonings":["1 ч.л. кимион","1 ч.л. пушен червен пипер","щипка сол","няколко капки сок от лайм или лимон"]},"nl":{"name":"Burritobowl met bonen en tofu","description":"Kidneybonen en gekruide tofu met mais, paprika en verse tomaat, zonder rijst","instructions":["Laat de bonen en de mais uitle